PREDICTED_PLANNED_PNL_ALIAS_TOL_EUR = 1e-6
DA_PRECOMMIT_REPLAY_TOL_EUR = 1e-6


BENCHMARK_PATH_TYPES = ("model", "naive", "rhpf", "ghpf")


def resolve_benchmark_paths(
    benchmark_mode: str = "full",
    *,
    enable_naive: bool | None = None,
    enable_rolling_pf: bool | None = None,
    enable_global_pf: bool | None = None,
    enable_global_perfect_foresight: bool = False,
) -> tuple[str, dict[str, bool]]:
    """Resolve benchmark execution flags without running any benchmark branch."""
    raw_mode = str(benchmark_mode or "full").strip().lower()
    mode_alias = {
        "rolling_pf": "rhpf",
        "rolling_pf_only": "rhpf_only",
        "perfect_foresight": "rhpf",
        "perfect_foresight_only": "rhpf_only",
    }
    mode = mode_alias.get(raw_mode, raw_mode)
    if mode in {"global_pf", "global_pf_only", "global_perfect_foresight", "global_perfect_foresight_only", "ghpf", "ghpf_only"}:
        raise ValueError("global perfect-foresight benchmark has been removed; use rolling PF/RHPF instead")
    if mode not in {"full", "model_only", "naive_only", "rhpf_only", "selected"}:
        raise ValueError(
            "benchmark_mode must be one of: full, model_only, naive_only, rhpf_only, selected"
        )
    if mode == "selected":
        paths = {
            "model": True,
            "naive": True if enable_naive is None else bool(enable_naive),
            "rhpf": True if enable_rolling_pf is None else bool(enable_rolling_pf),
            "ghpf": False,
        }
    else:
        paths = {
            "model": mode in {"full", "model_only"},
            "naive": mode in {"full", "naive_only"},
            "rhpf": mode in {"full", "rhpf_only"},
            "ghpf": False,
        }
        if enable_naive is not None:
            paths["naive"] = bool(enable_naive)
        if enable_rolling_pf is not None:
            paths["rhpf"] = bool(enable_rolling_pf)
        # Global hindsight PF has been removed. Keep the key false for schema
        # compatibility, but never execute or report a GHPF path.
        paths["ghpf"] = False
    return mode, {k: bool(paths.get(k, False)) for k in BENCHMARK_PATH_TYPES}


def apply_benchmark_availability_to_summary(
    summary: dict[str, object],
    *,
    benchmark_mode: str,
    benchmark_paths: dict[str, bool],
) -> dict[str, object]:
    """Mask disabled benchmark economics so unavailable paths never look like valid zero-PnL results."""
    out = dict(summary)
    enabled = [p for p in BENCHMARK_PATH_TYPES if bool(benchmark_paths.get(p, False))]
    disabled = [p for p in BENCHMARK_PATH_TYPES if p not in enabled]
    out["benchmark_mode"] = str(benchmark_mode)
    out["enabled_paths"] = ",".join(enabled)
    out["disabled_paths"] = ",".join(disabled)
    for p in BENCHMARK_PATH_TYPES:
        out[f"{p}_available"] = float(1.0 if benchmark_paths.get(p, False) else 0.0)
    out["rolling_pf_available"] = float(1.0 if benchmark_paths.get("rhpf", False) else 0.0) * float(
        pd.to_numeric(pd.Series([out.get("rolling_pf_available", out.get("rhpf_available", 1.0))]), errors="coerce")
        .fillna(0.0)
        .iloc[0]
    )
    out["rhpf_available"] = out["rolling_pf_available"]
    out["global_pf_available"] = float(1.0 if benchmark_paths.get("ghpf", False) else 0.0) * float(
        pd.to_numeric(pd.Series([out.get("global_pf_available", out.get("global_perfect_foresight_available", 1.0))]), errors="coerce")
        .fillna(0.0)
        .iloc[0]
    )
    out["global_perfect_foresight_available"] = out["global_pf_available"]
    out["ghpf_available"] = out["global_pf_available"]

    disabled_keys = {
        "model": [
            "realized_total_pnl_eur",
            "model_total_pnl_eur",
            "realized_market_pnl_eur",
            "realized_vs_perfect_foresight_ratio_multi_market",
            "realized_vs_perfect_foresight_pct",
            "realized_vs_global_hindsight_perfect_foresight_upper_bound_pct",
        ],
        "naive": [
            "naive_total_pnl_eur",
            "capture_ratio_vs_naive",
            "model_realized_vs_naive_realized_ratio",
        ],
        "rhpf": [
            "rolling_perfect_foresight_same_rules_total_pnl_eur",
            "same_rules_rolling_pf_total_pnl_eur",
            "rolling_pf_reported_total_pnl_eur",
            "rolling_pf_reported_available",
            "rolling_pf_reported_is_solver",
            "rolling_pf_solver_pnl_eur",
            "rolling_pf_selected_incumbent_pnl_eur",
            "rhpf_total_pnl_eur",
            "cost_of_forecast_error_total_eur",
            "pnl_gap_total_eur",
            "economic_opportunity_gap_ratio",
            "realized_vs_perfect_foresight_ratio_multi_market",
            "realized_vs_perfect_foresight_pct",
        ],
        "ghpf": [
            "global_hindsight_perfect_foresight_upper_bound_total_pnl_eur",
            "global_hindsight_perfect_foresight_upper_bound_market_pnl_eur",
            "global_pf_solver_solution_eur",
            "global_pf_selected_incumbent_pnl_eur",
            "ghpf_total_pnl_eur",
            "realized_vs_global_hindsight_perfect_foresight_upper_bound_pct",
        ],
    }
    for path, keys in disabled_keys.items():
        if not benchmark_paths.get(path, False):
            for key in keys:
                out[key] = float("nan")

    if benchmark_paths.get("model", False):
        out["model_total_pnl_eur"] = out.get("realized_total_pnl_eur", float("nan"))
    if benchmark_paths.get("rhpf", False):
        out["rhpf_total_pnl_eur"] = out.get("rolling_perfect_foresight_same_rules_total_pnl_eur", float("nan"))
    if benchmark_paths.get("ghpf", False):
        out["ghpf_total_pnl_eur"] = out.get("global_hindsight_perfect_foresight_upper_bound_total_pnl_eur", float("nan"))
    return out


def should_report_rolling_pf_solver_failed(
    *,
    strict_simulation_validity: bool,
    rolling_pf_enabled: bool,
    rolling_pf_available: float,
) -> bool:
    """RHPF failure is fatal only when the RHPF benchmark was requested."""
    return bool(strict_simulation_validity) and bool(rolling_pf_enabled) and float(rolling_pf_available) < 0.5


def _utc_now_iso() -> str:
    return pd.Timestamp.now(tz="UTC").strftime("%Y-%m-%dT%H:%M:%SZ")


def _json_safe(value: object) -> object:
    """Convert numpy/pandas objects and non-finite floats to strict JSON values."""
    if isinstance(value, dict):
        return {str(k): _json_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_json_safe(v) for v in value]
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, pd.Timestamp):
        return value.isoformat()
    if isinstance(value, np.generic):
        return _json_safe(value.item())
    if isinstance(value, float):
        return float(value) if np.isfinite(value) else None
    if isinstance(value, (int, str, bool)) or value is None:
        return value
    if not isinstance(value, (pd.DataFrame, pd.Series, np.ndarray)):
        try:
            if bool(pd.isna(value)):
                return None
        except Exception:
            pass
    return str(value)


def _atomic_write_json(path: str | Path, data: dict[str, object]) -> Path:
    """Atomically write JSON by replacing the target with a completed temp file."""
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    tmp = target.with_name(f".{target.name}.{os.getpid()}.{time.time_ns()}.tmp")
    try:
        with tmp.open("w", encoding="utf-8") as fh:
            json.dump(_json_safe(data), fh, ensure_ascii=False, indent=2, allow_nan=False)
            fh.write("\n")
        os.replace(tmp, target)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass
    return target


def _atomic_write_parquet(path: str | Path, df: pd.DataFrame) -> Path:
    """Atomically write Parquet by replacing the target with a completed temp file."""
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    tmp = target.with_name(f".{target.name}.{os.getpid()}.{time.time_ns()}.tmp.parquet")
    try:
        df.to_parquet(tmp, index=False)
        os.replace(tmp, target)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass
    return target


CHECKPOINT_STAGE_FILES = {
    "stage_01_model_realized": (
        "stage_01_model_realized_hourly.parquet",
        "stage_01_model_realized_summary.json",
    ),
    "stage_02_naive": (
        "stage_02_naive_hourly.parquet",
        "stage_02_naive_summary.json",
    ),
    "stage_03_rolling_pf": (
        "stage_03_rolling_pf_hourly.parquet",
        "stage_03_rolling_pf_summary.json",
    ),
    "stage_05_final": (
        "",
        "stage_05_final_summary.json",
    ),
}


def _checkpoint_summary(
    *,
    stage_name: str,
    stage_status: str,
    frame: pd.DataFrame | None,
    summary: dict[str, object] | None,
    metadata: dict[str, object],
) -> dict[str, object]:
    data: dict[str, object] = {
        **dict(metadata or {}),
        "stage_name": stage_name,
        "stage_status": stage_status,
        "row_count": int(len(frame)) if frame is not None else 0,
        "columns": list(frame.columns) if frame is not None else [],
    }
    if summary:
        for key in (
            "realized_total_pnl_eur",
            "predicted_total_pnl_eur",
            "naive_total_pnl_eur",
            "rolling_perfect_foresight_same_rules_total_pnl_eur",
            "global_hindsight_perfect_foresight_upper_bound_total_pnl_eur",
            "simulation_valid",
            "thesis_reportable",
            "invalid_reason",
            "fallback_used",
        ):
            if key in summary:
                data[key] = summary[key]
    if frame is not None and not frame.empty:
        pnl_candidates = {
            "realized_total_pnl_eur": "real_pnl_eur",
            "predicted_total_pnl_eur": "pred_pnl_eur",
            "naive_total_pnl_eur": "naive_pnl_eur",
            "rolling_pf_total_pnl_eur": "perfect_foresight_pnl_eur",
            "global_pf_total_pnl_eur": "global_perfect_foresight_pnl_eur",
        }
        for out_key, col in pnl_candidates.items():
            if out_key not in data and col in frame.columns:
                data[out_key] = float(pd.to_numeric(frame[col], errors="coerce").fillna(0.0).sum())
    return data


def _read_checkpoint_manifest(checkpoint_dir: Path) -> dict[str, object]:
    path = checkpoint_dir / "manifest.json"
    if not path.exists():
        return {}
    try:
        with path.open("r", encoding="utf-8") as fh:
            payload = json.load(fh)
        return payload if isinstance(payload, dict) else {}
    except Exception:
        return {}


def _update_checkpoint_manifest(
    checkpoint_dir: str | Path,
    *,
    metadata: dict[str, object],
    stage_name: str | None = None,
    stage_status: str | None = None,
    stage_files: list[str] | None = None,
    stage_started_at_utc: str | None = None,
    stage_completed_at_utc: str | None = None,
    final_complete: bool | None = None,
) -> Path:
    checkpoint_path = Path(checkpoint_dir)
    checkpoint_path.mkdir(parents=True, exist_ok=True)
    now = _utc_now_iso()
    manifest = _read_checkpoint_manifest(checkpoint_path)
    created_at = str(manifest.get("created_at_utc") or now)
    stages = manifest.get("stages", {})
    if not isinstance(stages, dict):
        stages = {}
    manifest.update(dict(metadata or {}))
    manifest["created_at_utc"] = created_at
    manifest["updated_at_utc"] = now
    manifest["stages"] = stages
    if final_complete is not None:
        manifest["final_complete"] = bool(final_complete)
    else:
        manifest.setdefault("final_complete", False)
    if stage_name:
        stages[str(stage_name)] = {
            "status": str(stage_status or "complete"),
            "started_at_utc": str(stage_started_at_utc or now),
            "completed_at_utc": str(stage_completed_at_utc or now),
            "files": list(stage_files or []),
        }
        if str(stage_status or "complete") == "complete":
            manifest["last_completed_stage"] = str(stage_name)
    manifest.setdefault("last_completed_stage", "")
    path = _atomic_write_json(checkpoint_path / "manifest.json", manifest)
    print(f"[CHECKPOINT] manifest updated: {path}")
    return path


def _write_checkpoint_run_status(
    checkpoint_dir: str | Path,
    *,
    status: str,
    metadata: dict[str, object] | None = None,
    error_type: str | None = None,
    error_message: str | None = None,
) -> Path:
    payload: dict[str, object] = {
        **dict(metadata or {}),
        "status": str(status),
        "updated_at_utc": _utc_now_iso(),
    }
    if error_type:
        payload["error_type"] = str(error_type)
    if error_message:
        payload["error_message"] = str(error_message)
    return _atomic_write_json(Path(checkpoint_dir) / "run_status.json", payload)


def _write_stage_checkpoint(
    checkpoint_dir: str | Path,
    *,
    stage_name: str,
    frame: pd.DataFrame | None,
    summary: dict[str, object] | None,
    metadata: dict[str, object],
    detail: str = "hourly",
    final_complete: bool = False,
) -> dict[str, object]:
    if stage_name not in CHECKPOINT_STAGE_FILES:
        raise ValueError(f"Unknown checkpoint stage: {stage_name}")
    checkpoint_path = Path(checkpoint_dir)
    checkpoint_path.mkdir(parents=True, exist_ok=True)
    started_at = _utc_now_iso()
    hourly_name, summary_name = CHECKPOINT_STAGE_FILES[stage_name]
    files: list[str] = []
    if hourly_name and str(detail).strip().lower() in {"hourly", "full"} and frame is not None:
        hourly_path = _atomic_write_parquet(checkpoint_path / hourly_name, frame)
        files.append(str(hourly_path))
    stage_summary = _checkpoint_summary(
        stage_name=stage_name,
        stage_status="complete",
        frame=frame,
        summary=summary,
        metadata=metadata,
    )
    summary_path = _atomic_write_json(checkpoint_path / summary_name, stage_summary)
    files.append(str(summary_path))
    completed_at = _utc_now_iso()
    _update_checkpoint_manifest(
        checkpoint_path,
        metadata=metadata,
        stage_name=stage_name,
        stage_status="complete",
        stage_files=files,
        stage_started_at_utc=started_at,
        stage_completed_at_utc=completed_at,
        final_complete=final_complete,
    )
    print(f"[CHECKPOINT] {stage_name} complete: {summary_path}")
    return stage_summary


def normalize_predicted_pnl_aliases(
    summary: dict[str, object],
    *,
    tolerance_eur: float = PREDICTED_PLANNED_PNL_ALIAS_TOL_EUR,
) -> dict[str, object]:
    """Use predicted_total_pnl_eur as canonical and planned_total_pnl_eur as a legacy alias."""
    out = dict(summary)
    predicted_present = "predicted_total_pnl_eur" in out
    planned_present = "planned_total_pnl_eur" in out
    if not predicted_present and planned_present:
        out["predicted_total_pnl_eur"] = out["planned_total_pnl_eur"]
        out["predicted_total_pnl_eur_source"] = "legacy_planned_total_pnl_eur"
        predicted_present = True
    if predicted_present and not planned_present:
        out["planned_total_pnl_eur"] = out["predicted_total_pnl_eur"]
        out["planned_total_pnl_eur_is_legacy_alias"] = 1.0
        return out
    if predicted_present and planned_present:
        pred = pd.to_numeric(pd.Series([out.get("predicted_total_pnl_eur")]), errors="coerce").iloc[0]
        planned = pd.to_numeric(pd.Series([out.get("planned_total_pnl_eur")]), errors="coerce").iloc[0]
        if pd.notna(pred) and pd.notna(planned) and abs(float(pred) - float(planned)) > float(tolerance_eur):
            raise ValueError(
                "predicted_total_pnl_eur and planned_total_pnl_eur differ; "
                f"predicted_total_pnl_eur={float(pred):.12g}, "
                f"planned_total_pnl_eur={float(planned):.12g}, "
                f"tolerance_eur={float(tolerance_eur):.12g}"
            )
        out["planned_total_pnl_eur"] = out["predicted_total_pnl_eur"]
        out["planned_total_pnl_eur_is_legacy_alias"] = 1.0
    return out


