    def _split_activation_revenue_components(
        self,
        *,
        delivered_pos_mwh: float,
        delivered_neg_mwh: float,
        bem_only_pos_mwh: float,
        bem_only_neg_mwh: float,
        act_pos_price_eur_mwh: float,
        act_neg_price_eur_mwh: float,
        bcm_linked_pos_mwh: float | None = None,
        bcm_linked_neg_mwh: float | None = None,
    ) -> dict[str, float]:
        """Split activation revenue into BCM-linked and BEM-only components."""
        d_pos = max(0.0, float(delivered_pos_mwh))
        d_neg = max(0.0, float(delivered_neg_mwh))
        b_pos = max(0.0, float(bem_only_pos_mwh))
        b_neg = max(0.0, float(bem_only_neg_mwh))
        p_pos = float(act_pos_price_eur_mwh)
        p_neg = float(self._neg_activation_provider_value(float(act_neg_price_eur_mwh)))

        # Clamp BEM-only delivered share to total delivered activation.
        b_pos = min(b_pos, d_pos)
        b_neg = min(b_neg, d_neg)
        if bcm_linked_pos_mwh is None:
            c_pos = max(0.0, d_pos - b_pos)
            method = "obligation_hour_fallback"
        else:
            c_pos = max(0.0, min(float(bcm_linked_pos_mwh), d_pos))
            method = "source_mwh"
        if bcm_linked_neg_mwh is None:
            c_neg = max(0.0, d_neg - b_neg)
        else:
            c_neg = max(0.0, min(float(bcm_linked_neg_mwh), d_neg))

        total_pos_source_mwh = max(0.0, b_pos + c_pos)
        total_neg_source_mwh = max(0.0, b_neg + c_neg)
        bcm_pos_share = float(c_pos / total_pos_source_mwh) if total_pos_source_mwh > 1e-12 else 0.0
        bem_pos_share = float(b_pos / total_pos_source_mwh) if total_pos_source_mwh > 1e-12 else 0.0
        bcm_neg_share = float(c_neg / total_neg_source_mwh) if total_neg_source_mwh > 1e-12 else 0.0
        bem_neg_share = float(b_neg / total_neg_source_mwh) if total_neg_source_mwh > 1e-12 else 0.0
        total_source_mwh = max(0.0, total_pos_source_mwh + total_neg_source_mwh)
        bcm_total_share = float((c_pos + c_neg) / total_source_mwh) if total_source_mwh > 1e-12 else 0.0
        bem_total_share = float((b_pos + b_neg) / total_source_mwh) if total_source_mwh > 1e-12 else 0.0

        bem_pos_rev = b_pos * p_pos
        bcm_pos_rev = c_pos * p_pos
        bem_neg_rev = b_neg * p_neg
        bcm_neg_rev = c_neg * p_neg

        return {
            "bcm_linked_pos_activation_mwh": float(c_pos),
            "bcm_linked_neg_activation_mwh": float(c_neg),
            "bem_only_pos_activation_mwh": float(b_pos),
            "bem_only_neg_activation_mwh": float(b_neg),
            "bem_only_pos_activation_revenue_eur": float(bem_pos_rev),
            "bem_only_neg_activation_revenue_eur": float(bem_neg_rev),
            "bem_only_activation_revenue_eur": float(bem_pos_rev + bem_neg_rev),
            "bcm_linked_pos_activation_revenue_eur": float(bcm_pos_rev),
            "bcm_linked_neg_activation_revenue_eur": float(bcm_neg_rev),
            "bcm_linked_activation_revenue_eur": float(bcm_pos_rev + bcm_neg_rev),
            "activation_revenue_reconciled_eur": float(bem_pos_rev + bem_neg_rev + bcm_pos_rev + bcm_neg_rev),
            "bcm_linked_activation_revenue_allocation_share": float(bcm_total_share),
            "bem_only_activation_revenue_allocation_share": float(bem_total_share),
            "bcm_linked_pos_activation_revenue_allocation_share": float(bcm_pos_share),
            "bem_only_pos_activation_revenue_allocation_share": float(bem_pos_share),
            "bcm_linked_neg_activation_revenue_allocation_share": float(bcm_neg_share),
            "bem_only_neg_activation_revenue_allocation_share": float(bem_neg_share),
            "activation_split_method": method,
        }

    @staticmethod
    def _missed_capacity_validation_components(hourly: pd.DataFrame) -> dict[str, object]:
        """Classify missed-capacity diagnostics using true BCM capacity evidence only."""
        def _num(col: str, default: float = 0.0) -> pd.Series:
            if col in hourly.columns:
                return pd.to_numeric(hourly[col], errors="coerce").fillna(float(default))
            return pd.Series(float(default), index=hourly.index, dtype="float64")

        generic_pos = _num("real_missed_capacity_pos_mw")
        generic_neg = _num("real_missed_capacity_neg_mw")
        true_bcm_sub_pos = _num("real_submitted_bcm_capacity_pos_mw")
        true_bcm_sub_neg = _num("real_submitted_bcm_capacity_neg_mw")
        true_bcm_locked_pos = _num("real_locked_bcm_capacity_pos_mw")
        true_bcm_locked_neg = _num("real_locked_bcm_capacity_neg_mw")
        true_bcm_awarded_pos = _num("real_bcm_awarded_capacity_pos_mw")
        true_bcm_awarded_neg = _num("real_bcm_awarded_capacity_neg_mw")
        true_bcm_executed_pos = _num("real_executed_bcm_capacity_pos_mw")
        true_bcm_executed_neg = _num("real_executed_bcm_capacity_neg_mw")
        bem_sub_pos = _num("real_bem_only_submitted_pos_mw") + _num("real_submitted_bem_only_pos_mw")
        bem_sub_neg = _num("real_bem_only_submitted_neg_mw") + _num("real_submitted_bem_only_neg_mw")

        true_bcm_pos_evidence = (
            true_bcm_sub_pos.abs()
            + true_bcm_locked_pos.abs()
            + true_bcm_awarded_pos.abs()
            + true_bcm_executed_pos.abs()
        ) > 1e-9
        true_bcm_neg_evidence = (
            true_bcm_sub_neg.abs()
            + true_bcm_locked_neg.abs()
            + true_bcm_awarded_neg.abs()
            + true_bcm_executed_neg.abs()
        ) > 1e-9
        bem_pos_evidence = bem_sub_pos.abs() > 1e-9
        bem_neg_evidence = bem_sub_neg.abs() > 1e-9
        true_bcm_missed_pos = generic_pos.where(true_bcm_pos_evidence, 0.0)
        true_bcm_missed_neg = generic_neg.where(true_bcm_neg_evidence, 0.0)
        ignored_bem_pos = generic_pos.where(bem_pos_evidence & ~true_bcm_pos_evidence, 0.0)
        ignored_bem_neg = generic_neg.where(bem_neg_evidence & ~true_bcm_neg_evidence, 0.0)
        missed_true_bcm_total = float(true_bcm_missed_pos.sum() + true_bcm_missed_neg.sum())
        ignored_bem_total = float(ignored_bem_pos.sum() + ignored_bem_neg.sum())
        return {
            "generic_missed_capacity_pos_mw": generic_pos,
            "generic_missed_capacity_neg_mw": generic_neg,
            "missed_capacity_true_bcm_pos_mw": true_bcm_missed_pos,
            "missed_capacity_true_bcm_neg_mw": true_bcm_missed_neg,
            "missed_capacity_ignored_bem_only_pos_mw": ignored_bem_pos,
            "missed_capacity_ignored_bem_only_neg_mw": ignored_bem_neg,
            "missed_capacity_true_bcm_submitted_pos_mw": float(true_bcm_sub_pos.sum()),
            "missed_capacity_true_bcm_submitted_neg_mw": float(true_bcm_sub_neg.sum()),
            "missed_capacity_bem_only_submitted_pos_mw": float(bem_sub_pos.sum()),
            "missed_capacity_bem_only_submitted_neg_mw": float(bem_sub_neg.sum()),
            "missed_capacity_check_applied": float(true_bcm_pos_evidence.any() or true_bcm_neg_evidence.any()),
            "missed_capacity_ignored_bem_only_submission": float(ignored_bem_total > 1e-9),
            "missed_capacity_reason": (
                "true_bcm_capacity_missed"
                if missed_true_bcm_total > 1e-9
                else ("bem_only_activation_submission_ignored" if ignored_bem_total > 1e-9 else "none")
            ),
        }

    def _project_terminal_soc_with_known_flows(
        self,
        *,
        current_soc_mwh: float,
        fixed_future_charge_mwh: float = 0.0,
        fixed_future_discharge_mwh: float = 0.0,
        remaining_aux_losses_mwh: float = 0.0,
        existing_scheduled_id_internal_mwh: float = 0.0,
        fixed_future_act_neg_mwh: float = 0.0,
        fixed_future_act_pos_mwh: float = 0.0,
    ) -> dict[str, float]:
        """Project terminal SoC from known future physical flows only."""
        charge_effect = max(0.0, float(fixed_future_charge_mwh)) * float(self.eta_in)
        discharge_effect = max(0.0, float(fixed_future_discharge_mwh)) / max(float(self.eta_out), 1e-12)
        act_neg_effect = max(0.0, float(fixed_future_act_neg_mwh)) * float(self.eta_in)
        act_pos_effect = max(0.0, float(fixed_future_act_pos_mwh)) / max(float(self.eta_out), 1e-12)
        projected = (
            float(current_soc_mwh)
            + charge_effect
            + act_neg_effect
            + max(0.0, float(existing_scheduled_id_internal_mwh))
            - discharge_effect
            - act_pos_effect
            - max(0.0, float(remaining_aux_losses_mwh))
        )
        return {
            "terminal_soc_projection_base_soc_mwh": float(current_soc_mwh),
            "terminal_soc_projection_remaining_aux_losses_mwh": float(max(0.0, remaining_aux_losses_mwh)),
            "terminal_soc_projection_fixed_future_charge_mwh": float(max(0.0, fixed_future_charge_mwh)),
            "terminal_soc_projection_fixed_future_discharge_mwh": float(max(0.0, fixed_future_discharge_mwh)),
            "terminal_soc_projection_existing_scheduled_id_internal_mwh": float(
                max(0.0, existing_scheduled_id_internal_mwh)
            ),
            "projected_terminal_soc_without_new_id_mwh": float(projected),
        }

    def _schedule_terminal_id_recovery(
        self,
        *,
        projected_terminal_soc_without_new_id_mwh: float,
        current_soc_mwh: float,
        terminal_soc_target_mwh: float,
        residual_charge_mw: float,
        terminal_soc_safety_margin_mwh: float = 0.0,
        terminal_repair_known_future_aux_mwh: float = 0.0,
        terminal_repair_recovery_aux_mwh: float = 0.0,
        terminal_repair_aux_without_recovery_mwh: float = 0.0,
        provisional_scheduled_internal_mwh: float = 0.0,
        terminal_repair_projection_includes_aux_without_recovery: bool = True,
    ) -> dict[str, float | str]:
        """Size one-step technical ID recovery using grid-side MWh and eta_in."""
        safety_buffer_mwh = max(0.0, float(terminal_soc_safety_margin_mwh))
        target_mwh = float(terminal_soc_target_mwh)
        target_with_safety_mwh = target_mwh + safety_buffer_mwh
        # Single-source safety handling: safety is added once here and nowhere else.
        shortfall_before_aux = max(0.0, target_with_safety_mwh - float(projected_terminal_soc_without_new_id_mwh))
        known_future_aux_mwh = max(0.0, float(terminal_repair_known_future_aux_mwh))
        # The no-recovery terminal projection may already include OFF/STANDBY
        # auxiliary consumption for the delivery hour. A terminal ID buy can
        # switch that hour into TRADING aux. Size recovery for the incremental
        # aux delta, not for the stale no-recovery aux state.
        aux_without_recovery_mwh = max(0.0, float(terminal_repair_aux_without_recovery_mwh))
        aux_with_recovery_mwh = max(0.0, float(terminal_repair_recovery_aux_mwh))
        recovery_induced_aux_mwh = max(0.0, aux_with_recovery_mwh - aux_without_recovery_mwh)
        projection_includes_aux_without = bool(terminal_repair_projection_includes_aux_without_recovery)
        # If the no-ID projection already includes the recovery hour's
        # no-recovery aux state, only the incremental OFF/STANDBY -> TRADING
        # delta must be added. If the projection is pre-aux for the recovery
        # hour, size against the full post-recovery aux state. This avoids
        # ending at target - (trading_aux - off_aux) in hard-final-SoC runs.
        recovery_aux_mwh = recovery_induced_aux_mwh if projection_includes_aux_without else aux_with_recovery_mwh
        required_additional_internal = max(
            0.0,
            target_mwh
            + safety_buffer_mwh
            + known_future_aux_mwh
            + recovery_aux_mwh
            - float(projected_terminal_soc_without_new_id_mwh),
        )
        provisional_internal = max(0.0, float(provisional_scheduled_internal_mwh))
        # Recovery-hour auxiliary load is battery-supplied and is subtracted in
        # the same settlement hour. Allowing that aux in the room cap prevents
        # sizing recovery to hit the target before aux and ending at target-aux.
        room_internal = max(
            0.0,
            float(self.soc_max) + aux_with_recovery_mwh - (float(current_soc_mwh) + provisional_internal),
        )
        available_additional_internal = (
            max(0.0, float(residual_charge_mw)) * float(self.dt_h) * max(float(self.eta_in), 1e-12)
        )
        sched_additional_internal = min(
            required_additional_internal,
            room_internal,
            available_additional_internal,
        )
        sched_internal = provisional_internal + sched_additional_internal
        sched_grid = sched_internal / max(float(self.eta_in), 1e-12)
        projected_after_without_recovery_aux = float(projected_terminal_soc_without_new_id_mwh) + float(
            sched_additional_internal
        )
        projected_after = projected_after_without_recovery_aux - known_future_aux_mwh - recovery_aux_mwh
        # A second chance can recover remaining shortfall by adding more charge if there is
        # remaining residual headroom/power.
        iteration_count = 1.0
        replanned_due_to_residual = 0.0
        shortfall_after_repair = max(0.0, target_with_safety_mwh - projected_after)
        if shortfall_after_repair > 1e-9:
            extra_needed_internal = shortfall_after_repair
            extra_possible_internal = min(
                available_additional_internal - float(sched_additional_internal),
                room_internal - float(sched_additional_internal),
            )
            extra_internal = min(extra_needed_internal, max(0.0, extra_possible_internal))
            if extra_internal > 1e-9:
                iteration_count = 2.0
                replanned_due_to_residual = 1.0
                sched_additional_internal += float(extra_internal)
                sched_internal = provisional_internal + sched_additional_internal
                sched_grid = sched_internal / max(float(self.eta_in), 1e-12)
                projected_after_without_recovery_aux = float(projected_terminal_soc_without_new_id_mwh) + float(
                    sched_additional_internal
                )
                projected_after = projected_after_without_recovery_aux - known_future_aux_mwh - recovery_aux_mwh
                shortfall_after_repair = max(0.0, target_with_safety_mwh - projected_after)
        required_internal = provisional_internal + required_additional_internal
        feasible = float(sched_additional_internal + 1e-9 >= required_additional_internal + 0.0)
        if sched_additional_internal <= 1e-9 and shortfall_before_aux <= 1e-9:
            feasible = 1.0
        not_recoverable_reason = "none"
        if shortfall_after_repair > 1e-9 or (required_additional_internal > 1e-9 and feasible < 0.5):
            if max(0.0, float(residual_charge_mw)) <= 1e-9:
                not_recoverable_reason = "no_residual_charge_power"
            elif room_internal <= 1e-9:
                not_recoverable_reason = "soc_max_room_exhausted"
            else:
                not_recoverable_reason = "insufficient_remaining_id_capacity"
        return {
            "terminal_repair_shortfall_before_aux_mwh": float(shortfall_before_aux),
            "terminal_repair_known_future_aux_mwh": float(known_future_aux_mwh),
            "terminal_repair_recovery_aux_mwh": float(recovery_aux_mwh),
            "terminal_repair_safety_buffer_mwh": float(safety_buffer_mwh),
            "terminal_soc_target_with_safety_mwh": float(target_with_safety_mwh),
            "terminal_repair_required_additional_internal_mwh": float(required_additional_internal),
            "terminal_repair_required_internal_mwh": float(required_internal),
            "terminal_repair_required_grid_buy_mwh": float(required_internal / max(float(self.eta_in), 1e-12)),
            "terminal_recovery_required_internal_mwh": float(required_internal),
            "terminal_recovery_required_grid_mwh": float(required_internal / max(float(self.eta_in), 1e-12)),
            "terminal_repair_scheduled_additional_internal_mwh": float(sched_additional_internal),
            "terminal_repair_residual_charge_internal_capacity_mwh": float(available_additional_internal),
            "terminal_repair_residual_room_internal_mwh": float(room_internal),
            "terminal_soc_id_recourse_needed_internal_mwh": float(required_internal),
            "terminal_soc_id_recourse_scheduled_grid_mwh": float(sched_grid),
            "terminal_soc_id_recourse_scheduled_internal_mwh": float(sched_internal),
            "terminal_recovery_scheduled_grid_mwh": float(sched_grid),
            "terminal_recovery_scheduled_internal_mwh": float(sched_internal),
            "terminal_recovery_known_future_aux_mwh": float(known_future_aux_mwh),
            "terminal_recovery_remaining_known_future_aux_mwh": float(known_future_aux_mwh),
            "terminal_recovery_recovery_aux_mwh": float(recovery_aux_mwh),
            "terminal_recovery_aux_loss_included_mwh": float(known_future_aux_mwh + recovery_aux_mwh),
            "terminal_recovery_aux_without_recovery_mwh": float(aux_without_recovery_mwh),
            "terminal_recovery_aux_with_recovery_mwh": float(aux_with_recovery_mwh),
            "terminal_recovery_induced_aux_delta_mwh": float(recovery_induced_aux_mwh),
            "terminal_recovery_aux_sized_mwh": float(recovery_aux_mwh),
            "terminal_recovery_projection_includes_aux_without_recovery": float(projection_includes_aux_without),
            "terminal_recovery_recovery_hour_aux_mwh": float(aux_with_recovery_mwh),
            "terminal_recovery_recovery_induced_aux_mwh": float(recovery_induced_aux_mwh),
            "terminal_recovery_induced_aux_loss_mwh": float(recovery_induced_aux_mwh),
            "terminal_recovery_safety_buffer_mwh": float(safety_buffer_mwh),
            "terminal_repair_projected_final_soc_before_repair_mwh": float(projected_terminal_soc_without_new_id_mwh),
            "terminal_repair_projected_final_soc_after_repair_mwh": float(projected_after),
            "terminal_recovery_projected_final_soc_before_recovery_mwh": float(projected_terminal_soc_without_new_id_mwh),
            "terminal_recovery_projected_final_soc_after_recovery_mwh": float(projected_after),
            "terminal_recovery_projected_final_soc_before_mwh": float(projected_terminal_soc_without_new_id_mwh),
            "terminal_recovery_projected_final_soc_after_mwh": float(projected_after),
            "projected_terminal_soc_with_new_id_mwh": float(projected_after),
            "terminal_soc_id_recovery_safety_mwh": float(max(0.0, terminal_soc_safety_margin_mwh)),
            "terminal_soc_recovery_iteration_count": float(iteration_count),
            "terminal_recovery_iteration_count": float(iteration_count),
            "terminal_recovery_replanned_due_to_residual_shortfall": float(replanned_due_to_residual),
            "terminal_soc_recovery_feasible": float(feasible),
            "terminal_repair_physical_feasible": float(feasible),
            "terminal_recovery_physical_applied": float(sched_internal > provisional_internal + 1e-12),
            "terminal_recovery_under_sized_mwh": float(shortfall_after_repair),
            "terminal_recovery_remaining_shortfall_after_recovery_mwh": float(shortfall_after_repair),
            "terminal_recovery_physical_target_met": float(shortfall_after_repair <= 1e-9),
            "terminal_recovery_final_projection_passed": float(shortfall_after_repair <= 1e-9),
            "terminal_recovery_physical_shortfall_after_recovery_mwh": float(shortfall_after_repair),
            "terminal_repair_aux_included_in_sizing": 1.0 if recovery_aux_mwh > 0.0 else 0.0,
            "terminal_soc_not_recoverable_with_id": float(required_additional_internal > 1e-9 and feasible < 0.5),
            "terminal_soc_not_recoverable_reason": str(not_recoverable_reason),
        }

    @staticmethod
    def _terminal_recovery_remaining_shortfall_after_existing(
        *,
        projected_terminal_soc_without_new_recovery_mwh: float,
        existing_scheduled_terminal_recovery_internal_mwh: float,
        known_future_aux_mwh: float,
        terminal_soc_target_mwh: float,
        safety_buffer_mwh: float,
        existing_recovery_aux_without_recovery_mwh: float = 0.0,
        existing_recovery_aux_with_recovery_mwh: float = 0.0,
        existing_recovery_projection_includes_aux_without_recovery: bool = True,
    ) -> dict[str, float]:
        before_existing = float(projected_terminal_soc_without_new_recovery_mwh)
        existing_internal = max(0.0, float(existing_scheduled_terminal_recovery_internal_mwh))
        aux = max(0.0, float(known_future_aux_mwh))
        target = float(terminal_soc_target_mwh) + max(0.0, float(safety_buffer_mwh))
        existing_aux_without = max(0.0, float(existing_recovery_aux_without_recovery_mwh))
        existing_aux_with = max(0.0, float(existing_recovery_aux_with_recovery_mwh))
        existing_aux_delta = max(0.0, existing_aux_with - existing_aux_without)
        projection_includes_aux_without = bool(existing_recovery_projection_includes_aux_without_recovery)
        existing_aux_sized = existing_aux_delta if projection_includes_aux_without else existing_aux_with
        after_existing_before_aux = before_existing + existing_internal - aux
        after_existing = after_existing_before_aux - existing_aux_sized
        remaining = max(0.0, target - after_existing)
        return {
            "terminal_recovery_projected_final_soc_before_existing_recovery_mwh": float(before_existing),
            "terminal_recovery_existing_scheduled_internal_mwh": float(existing_internal),
            "terminal_recovery_existing_aux_without_recovery_mwh": float(existing_aux_without),
            "terminal_recovery_existing_aux_with_recovery_mwh": float(existing_aux_with),
            "terminal_recovery_existing_induced_aux_delta_mwh": float(existing_aux_delta),
            "terminal_recovery_existing_aux_sized_mwh": float(existing_aux_sized),
            "terminal_recovery_existing_projection_includes_aux_without_recovery": float(projection_includes_aux_without),
            "terminal_recovery_projected_final_soc_after_existing_before_aux_mwh": float(after_existing_before_aux),
            "terminal_recovery_projected_final_soc_after_existing_after_aux_mwh": float(after_existing),
            "terminal_recovery_projected_final_soc_after_existing_recovery_mwh": float(after_existing),
            "terminal_recovery_remaining_shortfall_internal_mwh": float(remaining),
            "terminal_recovery_remaining_shortfall_after_existing_recovery_mwh": float(remaining),
        }

    def _plan_id_rescue_for_next_hour(
        self,
        *,
        soc_next: float,
        reserve_pos_next_mw: float,
        reserve_neg_next_mw: float,
        da_charge_next_mw: float,
        da_discharge_next_mw: float,
        terminal_soc_target_mwh: float | None = None,
        projected_terminal_soc_without_new_id_mwh: float | None = None,
        remaining_known_losses_mwh: float = 0.0,
        terminal_soc_safety_margin_mwh: float = 0.0,
        terminal_recovery_allowed: bool = True,
        terminal_hard_soc_protection: bool = False,
        final_soc_tolerance_mwh: float = 1e-9,
    ) -> tuple[float, float, str]:
        """Compute ID rescue setpoints decided at t for execution in t+1."""
        id_charge = 0.0
        id_discharge = 0.0
        reason = "none"
        projected_raw = float(
            soc_next
            if projected_terminal_soc_without_new_id_mwh is None
            else projected_terminal_soc_without_new_id_mwh
        )
        known_future_aux_mwh = max(0.0, remaining_known_losses_mwh)
        projection_diag = self._project_terminal_soc_with_known_flows(
            current_soc_mwh=float(soc_next),
            fixed_future_charge_mwh=max(0.0, projected_raw - float(soc_next)) / max(float(self.eta_in), 1e-12),
            fixed_future_discharge_mwh=max(0.0, float(soc_next) - projected_raw) * max(float(self.eta_out), 1e-12),
            remaining_aux_losses_mwh=known_future_aux_mwh,
            existing_scheduled_id_internal_mwh=0.0,
        )
        projected_terminal_without_known_losses_mwh = float(
            projection_diag["projected_terminal_soc_without_new_id_mwh"] + known_future_aux_mwh
        )
        self._last_id_rescue_plan_diagnostics = {
            **projection_diag,
            "terminal_soc_projection_remaining_losses_mwh": float(max(0.0, remaining_known_losses_mwh)),
            "projected_terminal_soc_with_new_id_mwh": float(
                projection_diag["projected_terminal_soc_without_new_id_mwh"]
            ),
            "terminal_soc_id_recourse_needed_internal_mwh": 0.0,
            "terminal_soc_id_recourse_scheduled_grid_mwh": 0.0,
            "terminal_soc_id_recourse_scheduled_internal_mwh": 0.0,
            "terminal_soc_id_recovery_safety_mwh": float(max(0.0, terminal_soc_safety_margin_mwh)),
            "terminal_soc_recovery_iteration_count": 0.0,
            "terminal_soc_recovery_feasible": 1.0,
            "terminal_soc_not_recoverable_with_id": 0.0,
            "terminal_soc_not_recoverable_reason": "none",
        }
        reserve_pos_requirement_mwh = (
            (max(0.0, reserve_pos_next_mw) * self.reserve_activation_headroom_h) / max(self.eta_out, 1e-12)
        )
        reserve_neg_requirement_mwh = (
            (max(0.0, reserve_neg_next_mw) * self.reserve_activation_headroom_h) * self.eta_in
        )
        # Protected ID recovery is a validity guard, not an hourly aux-offset
        # mechanism. In non-reserve hours it should only repair physical lower
        # bound violations. Reserve safety is only relevant when a reserve
        # obligation exists and must be deliverable.
        req_soc_min_for_pos = self.soc_min + reserve_pos_requirement_mwh
        if reserve_pos_next_mw > 1e-12:
            req_soc_min_for_pos += float(self.reserve_headroom_safety_mwh)
        req_soc_max_for_neg = self.soc_max - reserve_neg_requirement_mwh
        if reserve_neg_next_mw > 1e-12:
            req_soc_max_for_neg -= float(self.reserve_headroom_safety_mwh)
        if soc_next < req_soc_min_for_pos:
            soc_gap_up = req_soc_min_for_pos - soc_next
            residual_stack = self._compute_canonical_power_stack(
                da_charge_mw=da_charge_next_mw,
                da_discharge_mw=da_discharge_next_mw,
                bcm_neg_obligation_mw=reserve_neg_next_mw,
                bcm_pos_obligation_mw=reserve_pos_next_mw,
            )
            residual_charge_mw = float(residual_stack["charge_residual_mw"])
            residual_total_mw = float(residual_stack["total_residual_mw"])
            residual_mw = max(0.0, min(residual_charge_mw, residual_total_mw))
            base_needed_grid_mwh = soc_gap_up / max(self.eta_in, 1e-12)
            base_needed_mw = base_needed_grid_mwh / max(self.dt_h, 1e-12)
            aux_with_id_mw, _ = self._state_aux_power_mw(
                charge_mw=max(0.0, float(da_charge_next_mw)),
                discharge_mw=max(0.0, float(da_discharge_next_mw)),
                reserve_pos_mw=max(0.0, float(reserve_pos_next_mw)),
                reserve_neg_mw=max(0.0, float(reserve_neg_next_mw)),
                act_pos_rate=0.0,
                act_neg_rate=0.0,
                id_charge_mw=min(float(base_needed_mw), residual_mw),
                id_discharge_mw=0.0,
            )
            protected_recovery_aux_mwh = max(0.0, float(aux_with_id_mw) * float(self.dt_h))
            protected_min_net_gain_mwh = max(
                0.0,
                float(getattr(self, "min_protected_recovery_net_gain_mwh", 0.01)),
            )
            protected_required_net_internal_mwh = max(float(soc_gap_up), protected_min_net_gain_mwh)
            # If the only reason for buying would be to offset the aux caused
            # by the ID action itself, suppress it. Terminal recovery handles
            # final-hour aux explicitly; protected recovery should not run every
            # hour just to keep SoC flat.
            protected_validity_gap_mwh = max(0.0, float(req_soc_min_for_pos) - float(soc_next))
            protected_required_internal_mwh = max(
                0.0,
                protected_required_net_internal_mwh + protected_recovery_aux_mwh,
            )
            needed_charge_mw = (
                protected_required_internal_mwh
                / max(float(self.eta_in), 1e-12)
                / max(float(self.dt_h), 1e-12)
            )
            id_charge = max(0.0, min(needed_charge_mw, residual_mw))
            protected_net_internal_mwh = (
                float(id_charge) * float(self.dt_h) * max(float(self.eta_in), 1e-12)
                - protected_recovery_aux_mwh
            )
            suppressed_zero_net = float(
                protected_net_internal_mwh + 1e-9 < protected_required_net_internal_mwh
            )
            aux_only_recovery = float(protected_validity_gap_mwh <= 1e-9 and protected_recovery_aux_mwh > 1e-12)
            if suppressed_zero_net >= 0.5 or aux_only_recovery >= 0.5:
                id_charge = 0.0
                reason = "none"
                protected_net_internal_mwh = 0.0
            else:
                reason = "reserve_obligation_recovery" if reserve_pos_next_mw > 1e-12 else "protected_soc_recovery"
            self._last_id_rescue_plan_diagnostics.update(
                {
                    "protected_recovery_required_internal_mwh": float(protected_required_internal_mwh),
                    "protected_recovery_required_net_internal_mwh": float(protected_required_net_internal_mwh),
                    "protected_recovery_aux_mwh": float(protected_recovery_aux_mwh),
                    "protected_recovery_net_internal_mwh": float(protected_net_internal_mwh),
                    "protected_recovery_min_net_gain_mwh": float(protected_min_net_gain_mwh),
                    "protected_recovery_suppressed_zero_net_effect": float(suppressed_zero_net),
                    "protected_recovery_suppressed_aux_only": float(aux_only_recovery),
                    "protected_recovery_validity_gap_mwh": float(protected_validity_gap_mwh),
                    "protected_recovery_sized_for_aux": 1.0,
                    "protected_recovery_residual_charge_mw": float(residual_mw),
                }
            )
        elif soc_next > req_soc_max_for_neg:
            soc_gap_down = soc_next - req_soc_max_for_neg
            needed_internal_discharge_mwh = soc_gap_down * self.eta_out
            needed_discharge_mw = needed_internal_discharge_mwh / max(self.dt_h, 1e-12)
            residual_discharge_mw = float(
                self._compute_canonical_power_stack(
                    da_charge_mw=da_charge_next_mw,
                    da_discharge_mw=da_discharge_next_mw,
                    bcm_neg_obligation_mw=reserve_neg_next_mw,
                    bcm_pos_obligation_mw=reserve_pos_next_mw,
                )["discharge_residual_mw"]
            )
            residual_total_mw = float(
                self._compute_canonical_power_stack(
                    da_charge_mw=da_charge_next_mw,
                    da_discharge_mw=da_discharge_next_mw,
                    bcm_neg_obligation_mw=reserve_neg_next_mw,
                    bcm_pos_obligation_mw=reserve_pos_next_mw,
                )["total_residual_mw"]
            )
            id_discharge = max(0.0, min(needed_discharge_mw, residual_discharge_mw, residual_total_mw))
            reason = "afrr_headroom_repair" if reserve_neg_next_mw > 1e-12 else "soc_max_repair"
            if (
                terminal_soc_target_mwh is not None
                and np.isfinite(float(terminal_soc_target_mwh))
                and bool(terminal_hard_soc_protection)
            ):
                target_with_margin = float(terminal_soc_target_mwh) + max(0.0, float(terminal_soc_safety_margin_mwh))
                terminal_soc_floor_mwh = (
                    float(terminal_soc_target_mwh) - max(0.0, float(final_soc_tolerance_mwh))
                    if bool(terminal_hard_soc_protection)
                    else target_with_margin
                )
                requested_upper_relief_mwh = max(0.0, float(id_discharge)) * max(float(self.dt_h), 1e-12)
                projected_terminal_before_relief = float(projected_raw)
                projected_surplus_internal = max(0.0, projected_terminal_before_relief - terminal_soc_floor_mwh)
                tentative_grid_sell_mwh = min(
                    requested_upper_relief_mwh,
                    projected_surplus_internal * max(float(self.eta_out), 1e-12),
                )
                aux_with_relief_mw, _ = self._state_aux_power_mw(
                    charge_mw=max(0.0, float(da_charge_next_mw)),
                    discharge_mw=max(0.0, float(da_discharge_next_mw)),
                    reserve_pos_mw=max(0.0, float(reserve_pos_next_mw)),
                    reserve_neg_mw=max(0.0, float(reserve_neg_next_mw)),
                    act_pos_rate=0.0,
                    act_neg_rate=0.0,
                    id_charge_mw=0.0,
                    id_discharge_mw=tentative_grid_sell_mwh / max(float(self.dt_h), 1e-12),
                )
                relief_aux_mwh = max(0.0, float(aux_with_relief_mw) * float(self.dt_h))
                allowed_upper_relief_mwh = max(
                    0.0,
                    (projected_terminal_before_relief - terminal_soc_floor_mwh - relief_aux_mwh)
                    * max(float(self.eta_out), 1e-12)
                )
                original_id_discharge = float(id_discharge)
                id_discharge = min(
                    float(id_discharge),
                    float(allowed_upper_relief_mwh) / max(float(self.dt_h), 1e-12),
                )
                actual_upper_relief_mwh = float(id_discharge) * max(float(self.dt_h), 1e-12)
                projected_terminal_after_relief = projected_terminal_before_relief - (
                    float(id_discharge) * float(self.dt_h) / max(float(self.eta_out), 1e-12)
                ) - (relief_aux_mwh if id_discharge > 1e-12 else 0.0)
                if original_id_discharge > 1e-12:
                    self._last_id_rescue_plan_diagnostics.update(
                        {
                            "upper_soc_relief_preserves_terminal_target": float(
                                projected_terminal_after_relief + 1e-9 >= terminal_soc_floor_mwh
                            ),
                            "upper_soc_relief_caused_terminal_shortfall": float(
                                projected_terminal_after_relief + 1e-9 < terminal_soc_floor_mwh
                            ),
                            "upper_soc_relief_projected_terminal_soc_after_relief_mwh": float(
                                projected_terminal_after_relief
                            ),
                            "upper_soc_relief_aux_mwh": float(relief_aux_mwh if id_discharge > 1e-12 else 0.0),
                            "upper_soc_relief_terminal_shortfall_prevented": float(id_discharge + 1e-12 < original_id_discharge),
                            "upper_soc_relief_origin_reason": str(reason),
                            "upper_soc_relief_original_id_discharge_mw": float(original_id_discharge),
                            "upper_soc_relief_terminal_preserving_id_discharge_mw": float(id_discharge),
                            "terminal_day_upper_soc_relief_capped": float(
                                bool(terminal_hard_soc_protection)
                                and actual_upper_relief_mwh + 1e-12 < requested_upper_relief_mwh
                            ),
                            "terminal_day_upper_soc_relief_requested_mwh": float(requested_upper_relief_mwh),
                            "terminal_day_upper_soc_relief_allowed_mwh": float(allowed_upper_relief_mwh),
                            "terminal_day_upper_soc_relief_blocked_mwh": float(
                                max(0.0, requested_upper_relief_mwh - actual_upper_relief_mwh)
                            ),
                            "terminal_day_upper_soc_relief_soc_floor_mwh": float(terminal_soc_floor_mwh),
                            "terminal_day_upper_soc_relief_projected_soc_before_mwh": float(
                                projected_terminal_before_relief
                            ),
                            "terminal_day_upper_soc_relief_projected_soc_after_mwh": float(
                                projected_terminal_after_relief
                            ),
                            "terminal_day_upper_soc_relief_reason": (
                                "protect_hard_final_soc" if bool(terminal_hard_soc_protection) else "not_terminal_hour"
                            ),
                        }
                    )
                if id_discharge <= 1e-12:
                    id_discharge = 0.0
                    reason = "none"
        if (
            terminal_soc_target_mwh is not None
            and np.isfinite(float(terminal_soc_target_mwh))
            and id_discharge <= 1e-12
        ):
            projected_without_base = float(projected_terminal_without_known_losses_mwh)
            terminal_need_internal = max(
                0.0,
                float(terminal_soc_target_mwh) + max(0.0, float(terminal_soc_safety_margin_mwh)) - projected_without_base,
            )
            if terminal_need_internal > 1e-9 and not bool(terminal_recovery_allowed):
                self._last_id_rescue_plan_diagnostics.update(
                    {
                        "terminal_recovery_suppressed_until_final_window": 1.0,
                        "terminal_recovery_suppressed_projected_shortfall_internal_mwh": float(
                            terminal_need_internal
                        ),
                        "terminal_recovery_suppressed_reason": "not_latest_terminal_recovery_window",
                    }
                )
            if terminal_need_internal > 1e-9 and bool(terminal_recovery_allowed):
                known_future_aux_mwh = max(0.0, float(remaining_known_losses_mwh))
                residual_stack = self._compute_canonical_power_stack(
                    da_charge_mw=da_charge_next_mw,
                    da_discharge_mw=da_discharge_next_mw,
                    id_buy_mw=id_charge,
                    id_sell_mw=0.0,
                    bcm_neg_obligation_mw=reserve_neg_next_mw,
                    bcm_pos_obligation_mw=reserve_pos_next_mw,
                )
                residual_charge_mw = float(residual_stack["charge_residual_mw"])
                residual_total_mw = float(residual_stack["total_residual_mw"])
                residual_mw = max(0.0, min(residual_charge_mw, residual_total_mw))
                target_with_margin = float(terminal_soc_target_mwh) + max(0.0, float(terminal_soc_safety_margin_mwh))
                base_shortfall_internal_mwh = max(0.0, target_with_margin - float(projected_without_base))
                base_grid_mwh = (
                    (base_shortfall_internal_mwh + known_future_aux_mwh)
                    / max(float(self.eta_in), 1e-12)
                )
                base_id_charge_mw = min(
                    residual_mw,
                    base_grid_mwh / max(float(self.dt_h), 1e-12),
                )
                aux_without_id_mw, _ = self._state_aux_power_mw(
                    charge_mw=max(0.0, float(da_charge_next_mw)),
                    discharge_mw=max(0.0, float(da_discharge_next_mw)),
                    reserve_pos_mw=max(0.0, float(reserve_pos_next_mw)),
                    reserve_neg_mw=max(0.0, float(reserve_neg_next_mw)),
                    act_pos_rate=0.0,
                    act_neg_rate=0.0,
                    id_charge_mw=float(id_charge),
                    id_discharge_mw=0.0,
                )
                aux_without_id_mwh = max(0.0, float(aux_without_id_mw) * float(self.dt_h))
                projection_includes_aux_without_recovery = bool(
                    aux_without_id_mwh <= 1e-12
                    or float(projected_without_base) <= float(soc_next) - aux_without_id_mwh + 1e-9
                )
                aux_with_id_mw, _ = self._state_aux_power_mw(
                    charge_mw=max(0.0, float(da_charge_next_mw)),
                    discharge_mw=max(0.0, float(da_discharge_next_mw)),
                    reserve_pos_mw=max(0.0, float(reserve_pos_next_mw)),
                    reserve_neg_mw=max(0.0, float(reserve_neg_next_mw)),
                    act_pos_rate=0.0,
                    act_neg_rate=0.0,
                    id_charge_mw=float(id_charge + base_id_charge_mw),
                    id_discharge_mw=0.0,
                )
                # Aux is battery-supplied in settlement, so terminal recovery
                # must cover the full same-hour aux state caused by the ID action.
                # In scaled aux mode the aux loss depends on the final ID size,
                # so iterate a few times until scheduled ID and aux agree.
                recovery_aux_mwh = max(0.0, float(aux_with_id_mw) * float(self.dt_h))
                recovery_diag: dict[str, float | str] = {}
                recovery_iteration_count = 0
                recovery_replanned_due_to_residual = 0.0
                previous_aux_mwh = np.nan
                for recovery_iteration_count in range(1, 4):
                    recovery_diag = self._schedule_terminal_id_recovery(
                        projected_terminal_soc_without_new_id_mwh=projected_without_base,
                        current_soc_mwh=float(soc_next),
                        terminal_soc_target_mwh=float(terminal_soc_target_mwh),
                        residual_charge_mw=residual_mw,
                        terminal_soc_safety_margin_mwh=float(terminal_soc_safety_margin_mwh),
                        terminal_repair_known_future_aux_mwh=known_future_aux_mwh,
                        terminal_repair_recovery_aux_mwh=recovery_aux_mwh,
                        terminal_repair_aux_without_recovery_mwh=aux_without_id_mwh,
                        terminal_repair_projection_includes_aux_without_recovery=projection_includes_aux_without_recovery,
                    )
                    scheduled_grid_for_aux = float(
                        recovery_diag.get("terminal_soc_id_recourse_scheduled_grid_mwh", 0.0)
                    )
                    scheduled_id_mw_for_aux = scheduled_grid_for_aux / max(float(self.dt_h), 1e-12)
                    aux_with_scheduled_id_mw, _ = self._state_aux_power_mw(
                        charge_mw=max(0.0, float(da_charge_next_mw)),
                        discharge_mw=max(0.0, float(da_discharge_next_mw)),
                        reserve_pos_mw=max(0.0, float(reserve_pos_next_mw)),
                        reserve_neg_mw=max(0.0, float(reserve_neg_next_mw)),
                        act_pos_rate=0.0,
                        act_neg_rate=0.0,
                        id_charge_mw=float(id_charge + scheduled_id_mw_for_aux),
                        id_discharge_mw=0.0,
                    )
                    recalculated_aux_mwh = max(0.0, float(aux_with_scheduled_id_mw) * float(self.dt_h))
                    if np.isfinite(previous_aux_mwh) and abs(recalculated_aux_mwh - recovery_aux_mwh) <= 1e-9:
                        break
                    if abs(recalculated_aux_mwh - recovery_aux_mwh) <= 1e-9:
                        break
                    previous_aux_mwh = float(recovery_aux_mwh)
                    recovery_aux_mwh = float(recalculated_aux_mwh)
                    recovery_replanned_due_to_residual = 1.0
                if recovery_diag:
                    recovery_diag["terminal_soc_recovery_iteration_count"] = float(recovery_iteration_count)
                    recovery_diag["terminal_recovery_iteration_count"] = float(recovery_iteration_count)
                    recovery_diag["terminal_recovery_replanned_due_to_residual_shortfall"] = float(
                        max(
                            recovery_replanned_due_to_residual,
                            float(recovery_diag.get("terminal_recovery_replanned_due_to_residual_shortfall", 0.0)),
                        )
                    )
                    recovery_diag["terminal_recovery_aux_loss_included_mwh"] = float(
                        known_future_aux_mwh
                        + (
                            max(0.0, float(recovery_aux_mwh) - float(aux_without_id_mwh))
                            if projection_includes_aux_without_recovery
                            else max(0.0, float(recovery_aux_mwh))
                        )
                    )
                    recovery_diag["terminal_recovery_aux_without_recovery_mwh"] = float(aux_without_id_mwh)
                    recovery_diag["terminal_recovery_aux_with_recovery_mwh"] = float(recovery_aux_mwh)
                    recovery_diag["terminal_recovery_induced_aux_delta_mwh"] = float(
                        max(0.0, float(recovery_aux_mwh) - float(aux_without_id_mwh))
                    )
                    recovery_diag["terminal_recovery_aux_sized_mwh"] = float(
                        max(0.0, float(recovery_aux_mwh) - float(aux_without_id_mwh))
                        if projection_includes_aux_without_recovery
                        else max(0.0, float(recovery_aux_mwh))
                    )
                    recovery_diag["terminal_recovery_projection_includes_aux_without_recovery"] = float(
                        projection_includes_aux_without_recovery
                    )
                scheduled_internal_mwh = float(
                    recovery_diag.get("terminal_soc_id_recourse_scheduled_internal_mwh", 0.0)
                )
                scheduled_grid_mwh = float(
                    recovery_diag.get("terminal_soc_id_recourse_scheduled_grid_mwh", 0.0)
                )
                add_id_charge_mw = scheduled_grid_mwh / max(float(self.dt_h), 1e-12)
                projected_without_new_id = float(
                    recovery_diag.get("terminal_repair_projected_final_soc_before_repair_mwh", projected_without_base)
                )
                projected_before_aux = float(projected_without_new_id + scheduled_internal_mwh)
                projected_after_aux = float(recovery_diag.get("projected_terminal_soc_with_new_id_mwh", projected_before_aux))
                post_aux_shortfall = max(0.0, target_with_margin - projected_after_aux)
                recovery_diag.update(
                    {
                        "terminal_soc_projection_id_extra_aux_losses_mwh": float(
                            recovery_diag.get("terminal_recovery_aux_sized_mwh", 0.0)
                        ),
                        "projected_terminal_soc_with_new_id_before_aux_mwh": float(projected_before_aux),
                        "projected_terminal_soc_without_new_id_mwh": float(projected_without_base),
                        "terminal_soc_recovery_post_aux_shortfall_mwh": float(post_aux_shortfall),
                        "terminal_recovery_projected_final_soc_before_recovery_mwh": float(projected_without_base),
                        "terminal_recovery_projected_final_soc_after_recovery_mwh": float(projected_after_aux),
                        "terminal_recovery_remaining_shortfall_after_recovery_mwh": float(post_aux_shortfall),
                        "terminal_recovery_final_projection_passed": float(post_aux_shortfall <= 1e-7),
                    }
                )
                if (
                    post_aux_shortfall > 1e-7
                    and str(recovery_diag.get("terminal_soc_not_recoverable_reason", "none")) == "none"
                ):
                    recovery_diag["terminal_soc_not_recoverable_reason"] = "post_aux_terminal_shortfall"
                if recovery_diag.get("terminal_soc_recovery_feasible", 0.0) and post_aux_shortfall <= 1e-7:
                    recovery_diag["terminal_soc_recovery_feasible"] = 1.0
                else:
                    recovery_diag["terminal_soc_recovery_feasible"] = 0.0
                id_charge += max(0.0, add_id_charge_mw)
                reason = (
                    "terminal_soc_recovery"
                    if float(recovery_diag.get("terminal_soc_recovery_feasible", 0.0)) >= 0.5
                    else "terminal_soc_not_recoverable_with_id"
                )
                self._last_id_rescue_plan_diagnostics.update(recovery_diag)
        return float(id_charge), float(id_discharge), str(reason)

    def _apply_bem_only_submission_guard(
        self,
        *,
        desired_bem_only_pos_mw: float,
        desired_bem_only_neg_mw: float,
        soc_start_mwh: float,
        locked_reserve_pos_mw: float,
        locked_reserve_neg_mw: float,
        pred_act_pos: float,
        pred_act_neg: float,
        activation_rate_pos: float | None = None,
        activation_rate_neg: float | None = None,
        settlement_soc_start_mwh: float | None = None,
        da_charge_mw: float = 0.0,
        da_discharge_mw: float = 0.0,
        id_charge_mw: float = 0.0,
        id_discharge_mw: float = 0.0,
        preserve_da_lockbook: bool = False,
    ) -> dict[str, float | str]:
        desired_pos = max(0.0, float(desired_bem_only_pos_mw))
        desired_neg = max(0.0, float(desired_bem_only_neg_mw))
        locked_pos = max(0.0, float(locked_reserve_pos_mw))
        locked_neg = max(0.0, float(locked_reserve_neg_mw))
        da_only_violation = bool(
            self._is_da_only_permissions(self._strategy_permissions)
            and (
                desired_pos > 1e-12
                or desired_neg > 1e-12
                or locked_pos > 1e-12
                or locked_neg > 1e-12
            )
        )
        if self._is_da_only_permissions(self._strategy_permissions):
            return {
                "desired_bem_only_pos_mw": float(desired_bem_only_pos_mw),
                "desired_bem_only_neg_mw": float(desired_bem_only_neg_mw),
                "safe_bem_only_pos_mw": 0.0,
                "safe_bem_only_neg_mw": 0.0,
                "bem_only_submitted_pos_mw_before_guard": float(desired_bem_only_pos_mw),
                "bem_only_submitted_neg_mw_before_guard": float(desired_bem_only_neg_mw),
                "bem_only_submitted_pos_mw_after_guard": 0.0,
                "bem_only_submitted_neg_mw_after_guard": 0.0,
                "submitted_bem_only_pos_mw": 0.0,
                "submitted_bem_only_neg_mw": 0.0,
                "bem_only_pos_reduced_by_headroom_mw": float(desired_pos),
                "bem_only_neg_reduced_by_headroom_mw": float(desired_neg),
                "bem_only_headroom_guard_applied": float(da_only_violation),
                "bem_only_headroom_guard_reason": (
                    "da_only_market_isolation_violation" if da_only_violation else "da_only_market_isolation_skip"
                ),
                "reserve_buffer_repair_attempted": 0.0,
                "reserve_buffer_repair_scheduled_mwh": 0.0,
                "reserve_buffer_repair_cost_eur": 0.0,
                "reserve_buffer_repair_reason": "none",
                "reserve_buffer_replay_pass": 1.0,
                "reserve_buffer_derated_pos_mw": float(desired_pos),
                "reserve_buffer_derated_neg_mw": float(desired_neg),
                "reserve_buffer_rejected_reason": (
                    "da_only_market_isolation_violation" if da_only_violation else "none"
                ),
                "da_only_reserve_logic_reached": float(da_only_violation),
                "da_only_reserve_lockbook_written": 0.0,
                "da_only_activation_aware_guard_reached": float(da_only_violation),
                "da_only_reserve_invalidity_emitted": 0.0,
            }
        guard_soc_anchor = float(soc_start_mwh)
        settlement_soc_start = float(guard_soc_anchor)
        try:
            if settlement_soc_start_mwh is not None and np.isfinite(float(settlement_soc_start_mwh)):
                settlement_soc_start = float(settlement_soc_start_mwh)
        except Exception:
            settlement_soc_start = float(guard_soc_anchor)
        bem_guard_vs_settlement_soc_delta = float(guard_soc_anchor - settlement_soc_start)
        bem_guard_stale_soc_anchor = float(abs(bem_guard_vs_settlement_soc_delta) > 1e-6)
        # Settlement-equivalent guard: all BEM availability checks must use
        # the same physical SoC anchor that settlement will use for this hour.
        soc_start = float(settlement_soc_start)
        dt_h = max(float(self.dt_h), 1e-12)
        fallback_bem_rate = max(
            0.0,
            min(1.0, float(self.bem_activation_headroom_h) / max(float(self.dt_h), 1e-12)),
        )
        act_rate_pos = float(fallback_bem_rate)
        act_rate_neg = float(fallback_bem_rate)
        try:
            if activation_rate_pos is not None and np.isfinite(float(activation_rate_pos)):
                act_rate_pos = max(
                    float(fallback_bem_rate),
                    max(0.0, min(1.0, float(activation_rate_pos))),
                )
        except Exception:
            act_rate_pos = float(fallback_bem_rate)
        try:
            if activation_rate_neg is not None and np.isfinite(float(activation_rate_neg)):
                act_rate_neg = max(
                    float(fallback_bem_rate),
                    max(0.0, min(1.0, float(activation_rate_neg))),
                )
        except Exception:
            act_rate_neg = float(fallback_bem_rate)
        locked_pos_internal_mwh = (
            locked_pos
            * max(float(self.reserve_activation_headroom_h), act_rate_pos * dt_h)
            / max(self.eta_out, 1e-12)
        )
        locked_neg_internal_mwh = (
            locked_neg
            * max(float(self.reserve_activation_headroom_h), act_rate_neg * dt_h)
            * self.eta_in
        )
        locked_psv = self._compute_obligation_driven_protected_soc_bounds(
            soc_start_mwh=float(soc_start),
            required_headroom_pos_mwh=float(locked_pos_internal_mwh),
            required_headroom_neg_mwh=float(locked_neg_internal_mwh),
            locked_reserve_pos_mw=float(locked_pos),
            locked_reserve_neg_mw=float(locked_neg),
        )
        protected_soc_min_mwh = float(locked_psv["protected_soc_min_mwh"])
        protected_soc_max_mwh = float(locked_psv["protected_soc_max_mwh"])
        committed_charge_grid_mwh = max(0.0, float(da_charge_mw) + float(id_charge_mw)) * dt_h
        committed_discharge_grid_mwh = max(0.0, float(da_discharge_mw) + float(id_discharge_mw)) * dt_h
        soc_after_committed_mwh = (
            soc_start
            + committed_charge_grid_mwh * self.eta_in
            - committed_discharge_grid_mwh / max(self.eta_out, 1e-12)
        )
        available_discharge_energy_mwh = max(
            0.0,
            soc_after_committed_mwh
            - protected_soc_min_mwh
            - self.bem_only_headroom_safety_mwh,
        )
        available_charge_headroom_mwh = max(
            0.0,
            protected_soc_max_mwh
            - soc_after_committed_mwh
            - self.bem_only_headroom_safety_mwh,
        )
        if max(0.0, float(da_discharge_mw) + float(id_discharge_mw)) > 1e-12:
            available_discharge_energy_mwh = 0.0
        if max(0.0, float(da_charge_mw) + float(id_charge_mw)) > 1e-12:
            available_charge_headroom_mwh = 0.0
        max_pos_soc_mw = float("inf")
        max_neg_soc_mw = float("inf")
        if act_rate_pos > 1e-12:
            max_pos_soc_mw = (
                available_discharge_energy_mwh
                * max(self.eta_out, 1e-12)
                / max(act_rate_pos * dt_h, 1e-12)
            )
        if act_rate_neg > 1e-12:
            max_neg_soc_mw = (
                available_charge_headroom_mwh
                / max(self.eta_in * act_rate_neg * dt_h, 1e-12)
            )
        residual_stack = self._compute_canonical_power_stack(
            da_charge_mw=da_charge_mw,
            da_discharge_mw=da_discharge_mw,
            id_buy_mw=id_charge_mw,
            id_sell_mw=id_discharge_mw,
            bcm_neg_obligation_mw=locked_neg,
            bcm_pos_obligation_mw=locked_pos,
        )
        safe_pos = min(
            max_pos_soc_mw,
            float(residual_stack["discharge_residual_mw"]),
            float(residual_stack["total_residual_mw"]),
        )
        safe_neg = min(
            max_neg_soc_mw,
            float(residual_stack["charge_residual_mw"]),
            float(residual_stack["total_residual_mw"]),
        )
        safe_pos = max(0.0, float(safe_pos))
        safe_neg = max(0.0, float(safe_neg))
        guard_reason = "none"
        da_buy_preservation_caps_bem_neg = bool(preserve_da_lockbook) and float(da_charge_mw) > 1e-12
        da_sell_preservation_caps_bem_pos = bool(preserve_da_lockbook) and float(da_discharge_mw) > 1e-12
        if da_buy_preservation_caps_bem_neg:
            safe_neg = 0.0
        if da_sell_preservation_caps_bem_pos:
            safe_pos = 0.0
        if self.disable_bem_only:
            desired_pos = 0.0
            desired_neg = 0.0
            guard_reason = "disabled_by_config"

        submitted_pos = min(desired_pos, safe_pos)
        submitted_neg = min(desired_neg, safe_neg)
        if self.max_bem_only_bid_mw is not None:
            submitted_pos = min(submitted_pos, float(self.max_bem_only_bid_mw))
            submitted_neg = min(submitted_neg, float(self.max_bem_only_bid_mw))
        combined_directional_bid_cap_mw = max(0.0, float(getattr(self, "p_max_mw", 0.0)))
        max_bem_pos_by_combined_cap = max(0.0, combined_directional_bid_cap_mw - locked_pos)
        max_bem_neg_by_combined_cap = max(0.0, combined_directional_bid_cap_mw - locked_neg)
        pre_joint_pos = float(submitted_pos)
        pre_joint_neg = float(submitted_neg)
        submitted_pos = min(submitted_pos, max_bem_pos_by_combined_cap)
        submitted_neg = min(submitted_neg, max_bem_neg_by_combined_cap)
        bem_pos_derated_by_combined_cap = max(0.0, pre_joint_pos - submitted_pos)
        bem_neg_derated_by_combined_cap = max(0.0, pre_joint_neg - submitted_neg)
        combined_directional_bid_cap_applied = float(
            bem_pos_derated_by_combined_cap > 1e-9
            or bem_neg_derated_by_combined_cap > 1e-9
        )
        if combined_directional_bid_cap_applied > 0.5 and guard_reason == "none":
            guard_reason = "combined_directional_bid_cap"
        combined_afrr_pos_bid_mw = float(locked_pos + submitted_pos)
        combined_afrr_neg_bid_mw = float(locked_neg + submitted_neg)
        combined_afrr_pos_bid_cap_violation_mw = max(
            0.0,
            combined_afrr_pos_bid_mw - combined_directional_bid_cap_mw,
        )
        combined_afrr_neg_bid_cap_violation_mw = max(
            0.0,
            combined_afrr_neg_bid_mw - combined_directional_bid_cap_mw,
        )
        if (
            submitted_pos > float(residual_stack["discharge_residual_mw"]) + 1e-9
            or submitted_neg > float(residual_stack["charge_residual_mw"]) + 1e-9
        ):
            submitted_pos = min(submitted_pos, float(residual_stack["discharge_residual_mw"]))
            submitted_neg = min(submitted_neg, float(residual_stack["charge_residual_mw"]))
            if guard_reason == "none":
                guard_reason = "power_stack_cap"
        pre_activation_guard_pos = float(submitted_pos)
        pre_activation_guard_neg = float(submitted_neg)
        max_pos_by_activation_energy = float("inf")
        max_neg_by_activation_energy = float("inf")
        if act_rate_pos > 1e-12:
            max_pos_by_activation_energy = (
                available_discharge_energy_mwh
                * max(float(self.eta_out), 1e-12)
                / max(act_rate_pos * dt_h, 1e-12)
            )
            submitted_pos = min(submitted_pos, max(0.0, float(max_pos_by_activation_energy)))
        if act_rate_neg > 1e-12:
            max_neg_by_activation_energy = (
                available_charge_headroom_mwh
                / max(float(self.eta_in) * act_rate_neg * dt_h, 1e-12)
            )
            submitted_neg = min(submitted_neg, max(0.0, float(max_neg_by_activation_energy)))
        bem_activation_guard_aux_power_mw, _ = self._state_aux_power_mw(
            charge_mw=0.0,
            discharge_mw=0.0,
            reserve_pos_mw=max(0.0, locked_pos + float(pre_activation_guard_pos)),
            reserve_neg_mw=max(0.0, locked_neg + float(pre_activation_guard_neg)),
            act_pos_rate=float(act_rate_pos),
            act_neg_rate=float(act_rate_neg),
            id_charge_mw=0.0,
            id_discharge_mw=0.0,
        )
        bem_activation_guard_aux_mwh = max(0.0, float(bem_activation_guard_aux_power_mw) * dt_h)
        available_discharge_after_aux_mwh = max(
            0.0,
            float(available_discharge_energy_mwh) - float(bem_activation_guard_aux_mwh),
        )
        available_charge_after_aux_mwh = max(0.0, float(available_charge_headroom_mwh))
        if act_rate_pos > 1e-12:
            max_pos_by_activation_energy = min(
                float(max_pos_by_activation_energy),
                available_discharge_after_aux_mwh
                * max(float(self.eta_out), 1e-12)
                / max(act_rate_pos * dt_h, 1e-12),
            )
            submitted_pos = min(submitted_pos, max(0.0, float(max_pos_by_activation_energy)))
        if act_rate_neg > 1e-12:
            max_neg_by_activation_energy = min(
                float(max_neg_by_activation_energy),
                available_charge_after_aux_mwh
                / max(float(self.eta_in) * act_rate_neg * dt_h, 1e-12),
            )
            submitted_neg = min(submitted_neg, max(0.0, float(max_neg_by_activation_energy)))
        bem_pos_derated_by_activation_guard = max(0.0, pre_activation_guard_pos - float(submitted_pos))
        bem_neg_derated_by_activation_guard = max(0.0, pre_activation_guard_neg - float(submitted_neg))
        activation_energy_guard_applied = float(
            bem_pos_derated_by_activation_guard > 1e-9
            or bem_neg_derated_by_activation_guard > 1e-9
        )
        activation_energy_guard_reason = "none"
        if activation_energy_guard_applied > 0.5:
            if bem_pos_derated_by_activation_guard > 1e-9 and bem_neg_derated_by_activation_guard > 1e-9:
                activation_energy_guard_reason = "pos_neg_activation_energy_not_deliverable"
            elif bem_pos_derated_by_activation_guard > 1e-9:
                activation_energy_guard_reason = "pos_activation_energy_not_deliverable"
            else:
                activation_energy_guard_reason = "neg_activation_energy_not_deliverable"
            if guard_reason == "none":
                guard_reason = "activation_energy_guard"
        bem_neg_before_derate = float(desired_neg)
        bem_pos_before_derate = float(desired_pos)
        rounding_before_pos = float(submitted_pos)
        rounding_before_neg = float(submitted_neg)
        submitted_pos = self._round_market_bid_down_mw(
            submitted_pos,
            step_mw=self.afrr_bid_granularity_mw,
            min_mw=self.afrr_min_bid_size_mw,
        )
        submitted_neg = self._round_market_bid_down_mw(
            submitted_neg,
            step_mw=self.afrr_bid_granularity_mw,
            min_mw=self.afrr_min_bid_size_mw,
        )
        rounding_applied = (
            abs(rounding_before_pos - submitted_pos) > 1e-9
            or abs(rounding_before_neg - submitted_neg) > 1e-9
        )
        zeroed_below_min = (
            (rounding_before_pos > 1e-9 and submitted_pos <= 1e-9)
            or (rounding_before_neg > 1e-9 and submitted_neg <= 1e-9)
        )
        def _direction_zero_reason(
            *,
            direction: str,
            desired: float,
            safe: float,
            rounded_before: float,
            submitted: float,
        ) -> str:
            if desired <= 1e-9:
                return "none"
            if self.disable_bem_only:
                return "disabled_by_config"
            if submitted > 1e-9:
                return "none"
            if rounded_before > 1e-9:
                return "market_bid_below_min"
            if direction == "pos" and max_pos_soc_mw <= 1e-9:
                return "discharge_headroom_cap"
            if direction == "neg" and max_neg_soc_mw <= 1e-9:
                return "charge_headroom_cap"
            if direction == "pos" and da_sell_preservation_caps_bem_pos:
                return "discharge_headroom_cap"
            if direction == "neg" and da_buy_preservation_caps_bem_neg:
                return "charge_headroom_cap"
            if safe <= 1e-9:
                return "power_stack_cap"
            return "market_bid_below_min"

        zero_reason_pos = _direction_zero_reason(
            direction="pos",
            desired=desired_bem_only_pos_mw,
            safe=safe_pos,
            rounded_before=rounding_before_pos,
            submitted=submitted_pos,
        )
        zero_reason_neg = _direction_zero_reason(
            direction="neg",
            desired=desired_bem_only_neg_mw,
            safe=safe_neg,
            rounded_before=rounding_before_neg,
            submitted=submitted_neg,
        )
        if desired_pos > 1e-9 and submitted_pos <= 1e-9 and bem_pos_derated_by_combined_cap > 1e-9:
            zero_reason_pos = "combined_directional_bid_cap"
        if desired_neg > 1e-9 and submitted_neg <= 1e-9 and bem_neg_derated_by_combined_cap > 1e-9:
            zero_reason_neg = "combined_directional_bid_cap"
        if desired_pos > 1e-9 and submitted_pos <= 1e-9 and bem_pos_derated_by_activation_guard > 1e-9:
            zero_reason_pos = "activation_energy_guard"
        if desired_neg > 1e-9 and submitted_neg <= 1e-9 and bem_neg_derated_by_activation_guard > 1e-9:
            zero_reason_neg = "activation_energy_guard"
        if bem_guard_stale_soc_anchor > 0.5:
            if desired_pos > 1e-9 and submitted_pos <= 1e-9:
                zero_reason_pos = "bem_guard_stale_soc_anchor"
            if desired_neg > 1e-9 and submitted_neg <= 1e-9:
                zero_reason_neg = "bem_guard_stale_soc_anchor"
        if guard_reason == "none" and (
            abs(submitted_pos - desired_pos) > 1e-9 or abs(submitted_neg - desired_neg) > 1e-9
        ):
            if (
                desired_pos > float(residual_stack["discharge_residual_mw"]) + 1e-9
                or desired_neg > float(residual_stack["charge_residual_mw"]) + 1e-9
            ):
                guard_reason = "power_stack_cap"
            elif combined_directional_bid_cap_applied > 0.5:
                guard_reason = "combined_directional_bid_cap"
            elif activation_energy_guard_applied > 0.5:
                guard_reason = "activation_energy_guard"
            elif bem_guard_stale_soc_anchor > 0.5:
                guard_reason = "bem_guard_stale_soc_anchor"
            elif zeroed_below_min:
                guard_reason = "market_bid_below_min"
            elif rounding_applied:
                guard_reason = "market_bid_granularity_round_down"
            elif da_buy_preservation_caps_bem_neg and desired_neg > submitted_neg + 1e-9:
                guard_reason = "charge_headroom_cap"
            elif da_sell_preservation_caps_bem_pos and desired_pos > submitted_pos + 1e-9:
                guard_reason = "discharge_headroom_cap"
            else:
                guard_reason = "protected_soc_headroom_cap"
        guard_applied = float(guard_reason != "none")
        guarded_pos_internal_mwh = (
            float(submitted_pos)
            * max(float(self.bem_activation_headroom_h), float(act_rate_pos) * dt_h)
            / max(float(self.eta_out), 1e-12)
        )
        guarded_neg_internal_mwh = (
            float(submitted_neg)
            * max(float(self.bem_activation_headroom_h), float(act_rate_neg) * dt_h)
            * max(float(self.eta_in), 0.0)
        )
        # Settlement/protected-SoC validation evaluates the reserve envelope at
        # the pre-delivery SoC. Do not let same-hour DA/ID actions make an
        # otherwise unsafe BEM reserve submission appear feasible.
        pre_delivery_combined_psv = self._compute_obligation_driven_protected_soc_bounds(
            soc_start_mwh=float(soc_start),
            required_headroom_pos_mwh=float(locked_pos_internal_mwh + guarded_pos_internal_mwh),
            required_headroom_neg_mwh=float(locked_neg_internal_mwh + guarded_neg_internal_mwh),
            locked_reserve_pos_mw=float(locked_pos + submitted_pos),
            locked_reserve_neg_mw=float(locked_neg + submitted_neg),
        )
        combined_psv = self._compute_obligation_driven_protected_soc_bounds(
            soc_start_mwh=float(soc_start),
            required_headroom_pos_mwh=float(locked_pos_internal_mwh + guarded_pos_internal_mwh),
            required_headroom_neg_mwh=float(locked_neg_internal_mwh + guarded_neg_internal_mwh),
            locked_reserve_pos_mw=float(locked_pos + submitted_pos),
            locked_reserve_neg_mw=float(locked_neg + submitted_neg),
        )
        combined_min_soc_mwh = min(soc_after_committed_mwh, soc_after_committed_mwh - guarded_pos_internal_mwh)
        combined_max_soc_mwh = max(soc_after_committed_mwh, soc_after_committed_mwh + guarded_neg_internal_mwh)
        combined_replay_pass = (
            combined_min_soc_mwh >= float(self.soc_min) - 1e-9
            and combined_max_soc_mwh <= float(self.soc_max) + 1e-9
            and float(combined_psv["protected_soc_violation_pos_mwh"]) <= 1e-9
            and float(combined_psv["protected_soc_violation_neg_mwh"]) <= 1e-9
            and float(pre_delivery_combined_psv["protected_soc_violation_pos_mwh"]) <= 1e-9
            and float(pre_delivery_combined_psv["protected_soc_violation_neg_mwh"]) <= 1e-9
        )
        reserve_buffer_first_violation_ts_utc = ""
        pre_delivery_pos_violation = (
            float(pre_delivery_combined_psv["protected_soc_violation_pos_mwh"]) > 1e-9
        )
        pre_delivery_neg_violation = (
            float(pre_delivery_combined_psv["protected_soc_violation_neg_mwh"]) > 1e-9
        )
        if pre_delivery_pos_violation or pre_delivery_neg_violation:
            if pre_delivery_pos_violation:
                submitted_pos = 0.0
                zero_reason_pos = "protected_soc_prevented_pos"
            if pre_delivery_neg_violation:
                submitted_neg = 0.0
                zero_reason_neg = "protected_soc_prevented_neg"
            guarded_pos_internal_mwh = (
                float(submitted_pos)
                * max(float(self.bem_activation_headroom_h), float(act_rate_pos) * dt_h)
                / max(float(self.eta_out), 1e-12)
            )
            guarded_neg_internal_mwh = (
                float(submitted_neg)
                * max(float(self.bem_activation_headroom_h), float(act_rate_neg) * dt_h)
                * max(float(self.eta_in), 0.0)
            )
            pre_delivery_combined_psv = self._compute_obligation_driven_protected_soc_bounds(
                soc_start_mwh=float(soc_start),
                required_headroom_pos_mwh=float(locked_pos_internal_mwh + guarded_pos_internal_mwh),
                required_headroom_neg_mwh=float(locked_neg_internal_mwh + guarded_neg_internal_mwh),
                locked_reserve_pos_mw=float(locked_pos + submitted_pos),
                locked_reserve_neg_mw=float(locked_neg + submitted_neg),
            )
            combined_psv = self._compute_obligation_driven_protected_soc_bounds(
                soc_start_mwh=float(soc_start),
                required_headroom_pos_mwh=float(locked_pos_internal_mwh + guarded_pos_internal_mwh),
                required_headroom_neg_mwh=float(locked_neg_internal_mwh + guarded_neg_internal_mwh),
                locked_reserve_pos_mw=float(locked_pos + submitted_pos),
                locked_reserve_neg_mw=float(locked_neg + submitted_neg),
            )
            combined_min_soc_mwh = min(soc_after_committed_mwh, soc_after_committed_mwh - guarded_pos_internal_mwh)
            combined_max_soc_mwh = max(soc_after_committed_mwh, soc_after_committed_mwh + guarded_neg_internal_mwh)
            combined_replay_pass = (
                combined_min_soc_mwh >= float(self.soc_min) - 1e-9
                and combined_max_soc_mwh <= float(self.soc_max) + 1e-9
                and float(combined_psv["protected_soc_violation_pos_mwh"]) <= 1e-9
                and float(combined_psv["protected_soc_violation_neg_mwh"]) <= 1e-9
                and float(pre_delivery_combined_psv["protected_soc_violation_pos_mwh"]) <= 1e-9
                and float(pre_delivery_combined_psv["protected_soc_violation_neg_mwh"]) <= 1e-9
            )
            if guard_reason in {"none", "bem_guard_stale_soc_anchor"}:
                if pre_delivery_pos_violation and pre_delivery_neg_violation:
                    guard_reason = "protected_soc_prevented_pos_neg"
                elif pre_delivery_pos_violation:
                    guard_reason = "protected_soc_prevented_pos"
                else:
                    guard_reason = "protected_soc_prevented_neg"
        if not combined_replay_pass:
            reserve_buffer_first_violation_ts_utc = ""
            if guard_reason == "none":
                if (
                    float(combined_psv["protected_soc_violation_pos_mwh"]) > 1e-9
                    or float(pre_delivery_combined_psv["protected_soc_violation_pos_mwh"]) > 1e-9
                ):
                    guard_reason = "protected_soc_prevented_pos"
                elif (
                    float(combined_psv["protected_soc_violation_neg_mwh"]) > 1e-9
                    or float(pre_delivery_combined_psv["protected_soc_violation_neg_mwh"]) > 1e-9
                ):
                    guard_reason = "protected_soc_prevented_neg"
        multi_derated = bool(preserve_da_lockbook) and (
            abs(float(submitted_neg) - bem_neg_before_derate) > 1e-9
            or abs(float(submitted_pos) - bem_pos_before_derate) > 1e-9
        )
        multi_zero_reason = "none"
        if bool(preserve_da_lockbook):
            reasons = [r for r in (str(zero_reason_neg), str(zero_reason_pos), str(guard_reason)) if r != "none"]
            multi_zero_reason = reasons[0] if reasons else "none"
        return {
            "desired_bem_only_pos_mw": float(desired_bem_only_pos_mw),
            "desired_bem_only_neg_mw": float(desired_bem_only_neg_mw),
            "safe_bem_only_pos_mw": float(safe_pos),
            "safe_bem_only_neg_mw": float(safe_neg),
            "bem_only_submitted_pos_mw_before_guard": float(desired_bem_only_pos_mw),
            "bem_only_submitted_neg_mw_before_guard": float(desired_bem_only_neg_mw),
            "bem_only_submitted_pos_mw_after_guard": float(submitted_pos),
            "bem_only_submitted_neg_mw_after_guard": float(submitted_neg),
            "submitted_bem_only_pos_mw": float(submitted_pos),
            "submitted_bem_only_neg_mw": float(submitted_neg),
            "afrr_bid_market_rounding_applied": float(rounding_applied),
            "afrr_bid_market_rounding_before_pos_mw": float(rounding_before_pos),
            "afrr_bid_market_rounding_after_pos_mw": float(submitted_pos),
            "afrr_bid_market_rounding_before_neg_mw": float(rounding_before_neg),
            "afrr_bid_market_rounding_after_neg_mw": float(submitted_neg),
            "bid_market_rounding_zeroed_below_min": float(zeroed_below_min),
            "bem_only_pos_reduced_by_headroom_mw": float(max(0.0, desired_bem_only_pos_mw - submitted_pos)),
            "bem_only_neg_reduced_by_headroom_mw": float(max(0.0, desired_bem_only_neg_mw - submitted_neg)),
            "bem_only_headroom_guard_applied": guard_applied,
            "bem_only_headroom_guard_reason": str(guard_reason),
            "reserve_buffer_repair_attempted": float(
                max(0.0, float(id_charge_mw)) > 1e-12
                or max(0.0, float(id_discharge_mw)) > 1e-12
            ),
            "reserve_buffer_repair_scheduled_mwh": float(
                (max(0.0, float(id_charge_mw)) + max(0.0, float(id_discharge_mw))) * dt_h
            ),
            "reserve_buffer_repair_cost_eur": 0.0,
            "reserve_buffer_repair_reason": (
                "existing_id_repair_included"
                if max(0.0, float(id_charge_mw)) > 1e-12
                or max(0.0, float(id_discharge_mw)) > 1e-12
                else "none"
            ),
            "reserve_buffer_replay_pass": float(combined_replay_pass),
            "reserve_buffer_first_violation_ts_utc": str(reserve_buffer_first_violation_ts_utc),
            "reserve_buffer_required_soc_min_mwh": float(
                max(
                    float(combined_psv["protected_soc_min_mwh"]),
                    float(pre_delivery_combined_psv["protected_soc_min_mwh"]),
                )
            ),
            "reserve_buffer_required_soc_max_mwh": float(
                min(
                    float(combined_psv["protected_soc_max_mwh"]),
                    float(pre_delivery_combined_psv["protected_soc_max_mwh"]),
                )
            ),
            "reserve_buffer_derated_pos_mw": float(max(0.0, desired_bem_only_pos_mw - submitted_pos)),
            "reserve_buffer_derated_neg_mw": float(max(0.0, desired_bem_only_neg_mw - submitted_neg)),
            "reserve_buffer_rejected_reason": str(guard_reason if guard_reason != "none" else "none"),
            "bem_guard_available_charge_headroom_mwh": float(available_charge_headroom_mwh),
            "bem_guard_available_discharge_energy_mwh": float(available_discharge_energy_mwh),
            "bem_guard_max_neg_bem_mw": float(safe_neg),
            "bem_guard_max_pos_bem_mw": float(safe_pos),
            "bem_guard_requested_neg_bem_mw": float(desired_bem_only_neg_mw),
            "bem_guard_requested_pos_bem_mw": float(desired_bem_only_pos_mw),
            "bem_guard_submitted_neg_bem_mw": float(submitted_neg),
            "bem_guard_submitted_pos_bem_mw": float(submitted_pos),
            "bem_guard_derated_neg_bem_mw": float(max(0.0, desired_bem_only_neg_mw - submitted_neg)),
            "bem_guard_derated_pos_bem_mw": float(max(0.0, desired_bem_only_pos_mw - submitted_pos)),
            "bem_guard_zero_reason_neg": str(zero_reason_neg),
            "bem_guard_zero_reason_pos": str(zero_reason_pos),
            "bem_guard_soc_anchor_mwh": float(guard_soc_anchor),
            "settlement_soc_start_mwh": float(settlement_soc_start),
            "bem_guard_vs_settlement_soc_delta_mwh": float(bem_guard_vs_settlement_soc_delta),
            "bem_guard_stale_soc_anchor": float(bem_guard_stale_soc_anchor),
            "bem_guard_includes_da_lockbook": 1.0,
            "bem_guard_includes_bcm_obligations": 1.0,
            "bem_guard_includes_id_repair": 1.0,
            "bem_guard_safety_margin_mwh": float(self.bem_only_headroom_safety_mwh),
            "combined_afrr_directional_bid_cap_mw": float(combined_directional_bid_cap_mw),
            "combined_afrr_pos_bid_mw": float(locked_pos + submitted_pos),
            "combined_afrr_neg_bid_mw": float(locked_neg + submitted_neg),
            "combined_afrr_pos_bid_cap_violation_mw": float(
                max(0.0, locked_pos + submitted_pos - combined_directional_bid_cap_mw)
            ),
            "combined_afrr_neg_bid_cap_violation_mw": float(
                max(0.0, locked_neg + submitted_neg - combined_directional_bid_cap_mw)
            ),
            "bem_pos_derated_by_combined_directional_cap_mw": float(
                max(0.0, bem_pos_derated_by_combined_cap)
            ),
            "bem_neg_derated_by_combined_directional_cap_mw": float(
                max(0.0, bem_neg_derated_by_combined_cap)
            ),
            "combined_directional_bid_cap_applied": float(combined_directional_bid_cap_applied),
            "bem_activation_energy_guard_applied": float(activation_energy_guard_applied),
            "bem_pos_derated_by_activation_energy_guard_mw": float(bem_pos_derated_by_activation_guard),
            "bem_neg_derated_by_activation_energy_guard_mw": float(bem_neg_derated_by_activation_guard),
            "bem_activation_energy_guard_reason": str(activation_energy_guard_reason),
            "bem_activation_energy_guard_basis": "expected_activation_energy",
            "bem_expected_delivery_duration_h": float(dt_h),
            "bem_expected_delivery_pos_mwh": float(submitted_pos * act_rate_pos * dt_h),
            "bem_expected_delivery_neg_mwh": float(submitted_neg * act_rate_neg * dt_h),
            "bem_activation_energy_guard_aux_mwh": float(bem_activation_guard_aux_mwh),
            "bem_activation_energy_guard_available_discharge_after_aux_mwh": float(
                available_discharge_after_aux_mwh
            ),
            "bem_activation_energy_guard_available_charge_after_aux_mwh": float(
                available_charge_after_aux_mwh
            ),
            "bem_activation_energy_guard_rate_pos": float(act_rate_pos),
            "bem_activation_energy_guard_rate_neg": float(act_rate_neg),
            "bem_activation_energy_guard_max_pos_mw": float(
                max_pos_by_activation_energy if np.isfinite(max_pos_by_activation_energy) else np.nan
            ),
            "bem_activation_energy_guard_max_neg_mw": float(
                max_neg_by_activation_energy if np.isfinite(max_neg_by_activation_energy) else np.nan
            ),
            "multi_stack_soc_after_locked_da_mwh": float(soc_after_committed_mwh) if preserve_da_lockbook else 0.0,
            "multi_stack_available_charge_headroom_after_da_mwh": (
                float(available_charge_headroom_mwh) if preserve_da_lockbook else 0.0
            ),
            "multi_stack_available_discharge_energy_after_da_mwh": (
                float(available_discharge_energy_mwh) if preserve_da_lockbook else 0.0
            ),
            "multi_stack_bem_neg_before_derate_mw": float(bem_neg_before_derate) if preserve_da_lockbook else 0.0,
            "multi_stack_bem_pos_before_derate_mw": float(bem_pos_before_derate) if preserve_da_lockbook else 0.0,
            "multi_stack_bem_neg_after_derate_mw": float(submitted_neg) if preserve_da_lockbook else 0.0,
            "multi_stack_bem_pos_after_derate_mw": float(submitted_pos) if preserve_da_lockbook else 0.0,
            "multi_stack_bem_derated_to_preserve_da_lockbook": float(multi_derated),
            "multi_stack_combined_replay_pass": float(combined_replay_pass) if preserve_da_lockbook else 0.0,
            "multi_stack_combined_replay_min_soc_mwh": float(combined_min_soc_mwh) if preserve_da_lockbook else 0.0,
            "multi_stack_combined_replay_max_soc_mwh": float(combined_max_soc_mwh) if preserve_da_lockbook else 0.0,
            "multi_stack_da_lockbook_preserved": float(bool(preserve_da_lockbook)),
            "multi_stack_zero_reason": str(multi_zero_reason),
            "bem_only_protected_soc_min_mwh": float(protected_soc_min_mwh),
            "bem_only_protected_soc_max_mwh": float(protected_soc_max_mwh),
            "bem_only_soc_start_mwh": float(soc_start),
            "bem_only_guard_soc_now_mwh": float(soc_start),
            "bem_only_guard_protected_soc_min_mwh": float(
                max(
                    float(protected_soc_min_mwh),
                    float(pre_delivery_combined_psv["protected_soc_min_mwh"]),
                )
            ),
            "bem_only_guard_protected_soc_max_mwh": float(
                min(
                    float(protected_soc_max_mwh),
                    float(pre_delivery_combined_psv["protected_soc_max_mwh"]),
                )
            ),
            "bem_only_power_stack_charge_residual_mw": float(residual_stack["charge_residual_mw"]),
            "bem_only_power_stack_discharge_residual_mw": float(residual_stack["discharge_residual_mw"]),
            "bem_only_power_stack_total_residual_mw": float(residual_stack["total_residual_mw"]),
            "bem_only_power_stack_total_violation_mw": float(residual_stack["total_stack_violation_mw"]),
            "bem_only_pos_neg_exclusivity_applied": 0.0,
            "bem_only_disabled_by_config": float(self.disable_bem_only),
            "max_bem_only_bid_mw": float(self.max_bem_only_bid_mw) if self.max_bem_only_bid_mw is not None else float("nan"),
        }

    def _apply_bem_settlement_anchor_guard_to_clearing_record(
        self,
        *,
        clearing_rec: dict[str, float | str],
        settlement_soc_start_mwh: float,
        charge_mw: float,
        discharge_mw: float,
        id_charge_mw: float,
        id_discharge_mw: float,
        reserve_pos_mw: float,
        reserve_neg_mw: float,
        act_rate_pos: float,
        act_rate_neg: float,
    ) -> tuple[dict[str, float | str], float, float]:
        """Re-guard precleared BEM availability against physical settlement SoC."""
        if not bool(self._strategy_permissions.allow_bem_only):
            return clearing_rec, float(reserve_pos_mw), float(reserve_neg_mw)

        desired_pos = max(0.0, float(clearing_rec.get("bem_only_submitted_pos_mw", 0.0) or 0.0))
        desired_neg = max(0.0, float(clearing_rec.get("bem_only_submitted_neg_mw", 0.0) or 0.0))
        old_exec_pos = max(0.0, float(clearing_rec.get("bem_only_executed_pos_mw", desired_pos) or 0.0))
        old_exec_neg = max(0.0, float(clearing_rec.get("bem_only_executed_neg_mw", desired_neg) or 0.0))
        if desired_pos <= 1e-12 and desired_neg <= 1e-12 and old_exec_pos <= 1e-12 and old_exec_neg <= 1e-12:
            return clearing_rec, float(reserve_pos_mw), float(reserve_neg_mw)

        planned_anchor = float(
            clearing_rec.get("bem_guard_soc_anchor_mwh", settlement_soc_start_mwh)
            or settlement_soc_start_mwh
        )
        clearing_rec = dict(clearing_rec)
        clearing_rec.setdefault("fixed_reserve_obligation_pos_mw", float(max(0.0, reserve_pos_mw)))
        clearing_rec.setdefault("fixed_reserve_obligation_neg_mw", float(max(0.0, reserve_neg_mw)))
        clearing_rec.setdefault("real_fixed_reserve_obligation_pos_mw", float(max(0.0, reserve_pos_mw)))
        clearing_rec.setdefault("real_fixed_reserve_obligation_neg_mw", float(max(0.0, reserve_neg_mw)))
        locked_pos = max(
            0.0,
            self._required_number_from_mapping(
                clearing_rec,
                "fixed_reserve_obligation_pos_mw",
                label="bcm.fixed_reserve_obligation_pos_mw",
                reason="missing_source_of_truth_bcm_lockbook",
                fallback=0.0,
            ),
        )
        locked_neg = max(
            0.0,
            self._required_number_from_mapping(
                clearing_rec,
                "fixed_reserve_obligation_neg_mw",
                label="bcm.fixed_reserve_obligation_neg_mw",
                reason="missing_source_of_truth_bcm_lockbook",
                fallback=0.0,
            ),
        )
        if locked_pos <= 1e-12:
            locked_pos = max(0.0, float(reserve_pos_mw) - old_exec_pos)
        if locked_neg <= 1e-12:
            locked_neg = max(0.0, float(reserve_neg_mw) - old_exec_neg)

        guard = self._apply_bem_only_submission_guard(
            desired_bem_only_pos_mw=float(desired_pos),
            desired_bem_only_neg_mw=float(desired_neg),
            soc_start_mwh=float(planned_anchor),
            settlement_soc_start_mwh=float(settlement_soc_start_mwh),
            locked_reserve_pos_mw=float(locked_pos),
            locked_reserve_neg_mw=float(locked_neg),
            pred_act_pos=0.0,
            pred_act_neg=0.0,
            activation_rate_pos=float(act_rate_pos),
            activation_rate_neg=float(act_rate_neg),
            da_charge_mw=float(charge_mw),
            da_discharge_mw=float(discharge_mw),
            id_charge_mw=float(id_charge_mw),
            id_discharge_mw=float(id_discharge_mw),
            preserve_da_lockbook=bool(self._strategy_permissions.allow_da and self._strategy_permissions.allow_bem_only),
        )
        submitted_pos = max(0.0, float(guard.get("submitted_bem_only_pos_mw", 0.0) or 0.0))
        submitted_neg = max(0.0, float(guard.get("submitted_bem_only_neg_mw", 0.0) or 0.0))
        executed_pos = min(old_exec_pos, submitted_pos)
        executed_neg = min(old_exec_neg, submitted_neg)
        new_reserve_pos = float(max(0.0, float(reserve_pos_mw) - old_exec_pos) + executed_pos)
        new_reserve_neg = float(max(0.0, float(reserve_neg_mw) - old_exec_neg) + executed_neg)

        updated = dict(clearing_rec)
        updated.update(
            {
                "bem_only_submitted_pos_mw": float(submitted_pos),
                "bem_only_submitted_neg_mw": float(submitted_neg),
                "submitted_bem_only_pos_mw": float(submitted_pos),
                "submitted_bem_only_neg_mw": float(submitted_neg),
                "bem_only_executed_pos_mw": float(executed_pos),
                "bem_only_executed_neg_mw": float(executed_neg),
                "bem_source_pos_mw": float(executed_pos),
                "bem_source_neg_mw": float(executed_neg),
                "executed_reserve_pos_mw": float(new_reserve_pos),
                "executed_reserve_neg_mw": float(new_reserve_neg),
                "reserve_pos_mw": float(new_reserve_pos),
                "reserve_neg_mw": float(new_reserve_neg),
                "bem_only_executed_pos_mwh": float(executed_pos * max(0.0, float(act_rate_pos)) * float(self.dt_h)),
                "bem_only_executed_neg_mwh": float(executed_neg * max(0.0, float(act_rate_neg)) * float(self.dt_h)),
            }
        )
        for key, value in guard.items():
            updated[key] = value
        return updated, new_reserve_pos, new_reserve_neg

    def _compute_obligation_driven_protected_soc_bounds(
        self,
        *,
        soc_start_mwh: float,
        required_headroom_pos_mwh: float,
        required_headroom_neg_mwh: float,
        locked_reserve_pos_mw: float,
        locked_reserve_neg_mw: float,
        committed_bem_pos_mw: float = 0.0,
        committed_bem_neg_mw: float = 0.0,
        reserve_pos_mw: float = 0.0,
        reserve_neg_mw: float = 0.0,
    ) -> dict[str, float]:
        physical_soc_min_mwh = float(self.soc_min)
        physical_soc_max_mwh = float(self.soc_max)
        req_pos = max(0.0, float(required_headroom_pos_mwh))
        req_neg = max(0.0, float(required_headroom_neg_mwh))
        locked_pos = max(0.0, float(locked_reserve_pos_mw))
        locked_neg = max(0.0, float(locked_reserve_neg_mw))
        # Strict thesis validity: protected envelope is obligation-driven.
        # Submitted/current-hour reserve or BEM-only volumes do not create a
        # future deliverability obligation by themselves.
        ob_pos_active = float((locked_pos > 1e-9) or (req_pos > 1e-9))
        ob_neg_active = float((locked_neg > 1e-9) or (req_neg > 1e-9))
        buffer_pos = float(
            (self.reserve_headroom_safety_mwh + self.reserve_soc_projection_safety_mwh)
            if ob_pos_active > 0.5
            else 0.0
        )
        buffer_neg = float(
            (self.reserve_headroom_safety_mwh + self.reserve_soc_projection_safety_mwh)
            if ob_neg_active > 0.5
            else 0.0
        )
        protected_soc_min_mwh = float(physical_soc_min_mwh + (req_pos if ob_pos_active > 0.5 else 0.0) + buffer_pos)
        protected_soc_max_mwh = float(physical_soc_max_mwh - (req_neg if ob_neg_active > 0.5 else 0.0) - buffer_neg)
        soc_start = float(soc_start_mwh)
        protected_violation_pos = float(max(0.0, protected_soc_min_mwh - soc_start))
        protected_violation_neg = float(max(0.0, soc_start - protected_soc_max_mwh))
        physical_violation_pos = float(max(0.0, physical_soc_min_mwh - soc_start))
        physical_violation_neg = float(max(0.0, soc_start - physical_soc_max_mwh))
        violation_without_obligation = float(
            ((protected_violation_pos + protected_violation_neg) > 1e-9)
            and (ob_pos_active < 0.5)
            and (ob_neg_active < 0.5)
        )
        return {
            "physical_soc_min_mwh": physical_soc_min_mwh,
            "physical_soc_max_mwh": physical_soc_max_mwh,
            "obligation_headroom_pos_active": float(ob_pos_active),
            "obligation_headroom_neg_active": float(ob_neg_active),
            "protected_soc_min_mwh": float(protected_soc_min_mwh),
            "protected_soc_max_mwh": float(protected_soc_max_mwh),
            "protected_soc_buffer_pos_mwh": float(buffer_pos),
            "protected_soc_buffer_neg_mwh": float(buffer_neg),
            "protected_soc_violation_pos_mwh": float(protected_violation_pos),
            "protected_soc_violation_neg_mwh": float(protected_violation_neg),
            "protected_soc_violation_without_obligation": float(violation_without_obligation),
            "physical_soc_violation_pos_mwh": float(physical_violation_pos),
            "physical_soc_violation_neg_mwh": float(physical_violation_neg),
        }

    def _apply_market_clearing(
        self,
        *,
        target_time_utc: pd.Timestamp | None = None,
        is_perfect_foresight: bool = False,
        planned_charge_mw: float,
        planned_discharge_mw: float,
        planned_reserve_pos_mw: float,
        planned_reserve_neg_mw: float,
        planned_bem_only_pos_mw: float = 0.0,
        planned_bem_only_neg_mw: float = 0.0,
        pred_da_price: float,
        pred_da_price_p05: float | None = None,
        pred_da_price_p10: float | None = None,
        pred_da_price_p50: float | None = None,
        pred_da_price_p90: float | None = None,
        pred_da_price_p95: float | None = None,
        true_da_price: float,
        pred_cap_pos: float,
        true_cap_pos: float,
        pred_cap_neg: float,
        true_cap_neg: float,
        pred_act_pos: float,
        true_act_pos: float,
        pred_act_neg: float,
        true_act_neg: float,
        true_rate_pos: float,
        true_rate_neg: float,
        pred_rate_pos: float | None = None,
        pred_rate_neg: float | None = None,
        soc_now: float | None = None,
        settlement_soc_now: float | None = None,
        pred_act_pos_q10: float | None = None,
        pred_act_pos_q50: float | None = None,
        pred_act_pos_q90: float | None = None,
        pred_act_neg_q10: float | None = None,
        pred_act_neg_q50: float | None = None,
        pred_act_neg_q90: float | None = None,
        obligation_pos_mw: float = 0.0,
        obligation_neg_mw: float = 0.0,
        obligation_energy_pos: float | None = None,
        obligation_energy_neg: float | None = None,
        obligation_capacity_price_pos: float | None = None,
        obligation_capacity_price_neg: float | None = None,
        planned_reserve_pos_bins_mw: list[float] | None = None,
        planned_reserve_neg_bins_mw: list[float] | None = None,
        pred_cap_pos_bins_eur_mw: list[float] | None = None,
        pred_cap_neg_bins_eur_mw: list[float] | None = None,
    ) -> dict[str, float | str]:
        """Sequential market clearing: aFRR capacity -> DA -> aFRR activation."""
        perms = self._strategy_permissions
        allow_da = bool(perms.allow_da)
        allow_bcm = bool(perms.allow_bcm)
        allow_bem = bool(perms.allow_bem_only)
        ch_plan, dis_plan = self._normalize_da_bid(planned_charge_mw, planned_discharge_mw)
        res_pos_plan = max(0.0, float(planned_reserve_pos_mw))
        res_neg_plan = max(0.0, float(planned_reserve_neg_mw))
        bem_pos_plan = max(0.0, float(planned_bem_only_pos_mw))
        bem_neg_plan = max(0.0, float(planned_bem_only_neg_mw))
        if not allow_da:
            ch_plan = 0.0
            dis_plan = 0.0
        if not allow_bcm:
            res_pos_plan = 0.0
            res_neg_plan = 0.0
        if not allow_bem:
            bem_pos_plan = 0.0
            bem_neg_plan = 0.0
        ts = pd.to_datetime(target_time_utc, utc=True, errors="coerce")
        if pd.isna(ts):
            ts = pd.Timestamp("1970-01-01T00:00:00Z")
        da_execution_policy = str(getattr(self, "da_execution_policy", self.da_execution_mode)).strip().lower()
        bcm_block_info = assign_bcm_capacity_block(pd.Series([ts]))
        bcm_product_block_id = str(bcm_block_info["bcm_capacity_block_id"].iloc[0])
        bem_delivery_hour_start_utc = pd.to_datetime(ts, utc=True)
        bem_activation_price_decision_time_utc = bem_delivery_hour_start_utc - pd.Timedelta(hours=1)

        ob_pos = max(0.0, float(obligation_pos_mw)) if allow_bcm else 0.0
        ob_neg = max(0.0, float(obligation_neg_mw)) if allow_bcm else 0.0
        soc_ref = float(self.soc_init if soc_now is None else soc_now)
        settlement_soc_ref = float(soc_ref)
        try:
            if settlement_soc_now is not None and np.isfinite(float(settlement_soc_now)):
                settlement_soc_ref = float(settlement_soc_now)
        except Exception:
            settlement_soc_ref = float(soc_ref)
        n_bins = int(len(self.afrr_quantile_bins))

        def _finite_nonzero(value: object) -> float:
            try:
                value_f = float(pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0])
            except Exception:
                return float("nan")
            if np.isfinite(value_f) and abs(value_f) > 1e-12:
                return float(value_f)
            return float("nan")

        # Existing BCM obligations are pay-as-bid. The only authoritative
        # capacity settlement price here is the lockbook/obligation bid price.
        # Do not backfill it from activation, truth, or forecast capacity prices:
        # a missing obligation price must stay auditable as missing.
        obligation_capacity_price_pos_resolved = _finite_nonzero(obligation_capacity_price_pos)
        obligation_capacity_price_neg_resolved = _finite_nonzero(obligation_capacity_price_neg)

        if self.da_bid_fail_fast_debug:
            # Debug-mode hard guard: DA limit bids must not be built from missing or
            # degenerate quantile inputs.
            buy_q_name = str(getattr(self.bid_builder, "da_buy_limit_quantile", "p50")).lower()
            sell_q_name = str(getattr(self.bid_builder, "da_sell_limit_quantile", "p50")).lower()
            da_q_map = {
                "p05": pred_da_price_p05,
                "p10": pred_da_price_p10,
                "p50": pred_da_price if pred_da_price_p50 is None else pred_da_price_p50,
                "p90": pred_da_price_p90,
                "p95": pred_da_price_p95,
            }
            if ch_plan > 0.0:
                buy_q_val = da_q_map.get(buy_q_name)
                if buy_q_val is None or not np.isfinite(float(buy_q_val)):
                    raise RuntimeError(
                        f"DA fail-fast: missing/invalid buy quantile '{buy_q_name}' at {ts}; "
                        f"planned_charge_mw={ch_plan:.4f}, pred_da_price={float(pred_da_price):.6f}"
                    )
                if abs(float(buy_q_val)) <= 1e-12:
                    raise RuntimeError(
                        f"DA fail-fast: zero buy quantile '{buy_q_name}' at {ts}; "
                        f"planned_charge_mw={ch_plan:.4f}, pred_da_price={float(pred_da_price):.6f}"
                    )
            if dis_plan > 0.0:
                sell_q_val = da_q_map.get(sell_q_name)
                if sell_q_val is None or not np.isfinite(float(sell_q_val)):
                    raise RuntimeError(
                        f"DA fail-fast: missing/invalid sell quantile '{sell_q_name}' at {ts}; "
                        f"planned_discharge_mw={dis_plan:.4f}, pred_da_price={float(pred_da_price):.6f}"
                    )
                if abs(float(sell_q_val)) <= 1e-12:
                    raise RuntimeError(
                        f"DA fail-fast: zero sell quantile '{sell_q_name}' at {ts}; "
                        f"planned_discharge_mw={dis_plan:.4f}, pred_da_price={float(pred_da_price):.6f}"
                    )

        def _qlevel(q: str) -> float:
            try:
                return float(q.replace("p", "")) / 100.0
            except Exception:
                return float("nan")

        activation_guard_diags: dict[str, dict[str, float | str]] = {}

        def _dynamic_afrr_energy_price_with_guard(
            *,
            diag_key: str,
            side: str,
            pred_act_price: float,
            obligation_mw: float,
            activation_headroom_h: float,
            q10: float | None,
            q50: float | None,
            q90: float | None,
            true_act_price: float,
        ) -> float:
            price = self.bid_builder.dynamic_afrr_energy_price(
                side=side,
                pred_act_price=float(pred_act_price),
                soc_now_mwh=soc_ref,
                soc_min_mwh=self.soc_min,
                soc_max_mwh=self.soc_max,
                obligation_mw=float(obligation_mw),
                delivery_duration_h=self.dt_h,
                activation_headroom_h=float(activation_headroom_h),
                q10=q10,
                q50=q50,
                q90=q90,
                is_perfect_foresight=is_perfect_foresight,
                true_act_price=float(true_act_price),
                perfect_foresight_bid_at_true_price=bool(
                    is_perfect_foresight and str(diag_key).startswith("bem_")
                ),
            )
            activation_guard_diags[diag_key] = dict(
                getattr(self.bid_builder, "last_activation_price_guard_diagnostics", {})
            )
            return float(price)

        # Per-bin transparency payload (filled later with submitted/awarded/activated values).
        bin_payload: dict[str, float | str] = {}
        for b, q in enumerate(self.afrr_quantile_bins):
            q_level = _qlevel(str(q))
            bin_payload[f"afrr_bin_{b}_quantile"] = str(q)
            bin_payload[f"afrr_bin_{b}_quantile_level"] = float(q_level)
            bin_payload[f"submitted_afrr_pos_bin_{b}_mw"] = 0.0
            bin_payload[f"submitted_afrr_neg_bin_{b}_mw"] = 0.0
            bin_payload[f"submitted_afrr_pos_bin_{b}_price_eur_mw"] = 0.0
            bin_payload[f"submitted_afrr_neg_bin_{b}_price_eur_mw"] = 0.0
            bin_payload[f"executed_afrr_cap_pos_bin_{b}_mw"] = 0.0
            bin_payload[f"executed_afrr_cap_neg_bin_{b}_mw"] = 0.0
            bin_payload[f"executed_afrr_cap_pos_bin_{b}_price_eur_mw"] = 0.0
            bin_payload[f"executed_afrr_cap_neg_bin_{b}_price_eur_mw"] = 0.0
            bin_payload[f"executed_afrr_act_pos_bin_{b}_mw"] = 0.0
            bin_payload[f"executed_afrr_act_neg_bin_{b}_mw"] = 0.0
            bin_payload[f"executed_afrr_act_pos_bin_{b}_price_eur_mwh"] = 0.0
            bin_payload[f"executed_afrr_act_neg_bin_{b}_price_eur_mwh"] = 0.0
        free_bem_from_unawarded_reserve_pos = (
            max(0.0, float(res_pos_plan))
            if bool(allow_bem) and not (ob_pos > 0.0 or ob_neg > 0.0)
            else 0.0
        )
        free_bem_from_unawarded_reserve_neg = (
            max(0.0, float(res_neg_plan))
            if bool(allow_bem) and not (ob_pos > 0.0 or ob_neg > 0.0)
            else 0.0
        )
        # In multi/BEM mode, current-hour reserve variables without a BCM
        # lockbook obligation are treated as free BEM-only bids. They must be
        # guarded before activation clearing; otherwise raw RHPF reserve plans
        # can bypass protected-SoC/activation feasibility.
        bem_guard_desired_pos = max(float(bem_pos_plan), float(free_bem_from_unawarded_reserve_pos))
        bem_guard_desired_neg = max(float(bem_neg_plan), float(free_bem_from_unawarded_reserve_neg))
        bem_guard = self._apply_bem_only_submission_guard(
            desired_bem_only_pos_mw=float(bem_guard_desired_pos),
            desired_bem_only_neg_mw=float(bem_guard_desired_neg),
            soc_start_mwh=float(soc_ref),
            locked_reserve_pos_mw=float(ob_pos),
            locked_reserve_neg_mw=float(ob_neg),
            pred_act_pos=float(pred_act_pos),
            pred_act_neg=float(pred_act_neg),
            settlement_soc_start_mwh=float(settlement_soc_ref),
            activation_rate_pos=(
                float(true_rate_pos)
                if bool(is_perfect_foresight)
                else (
                    float(pred_rate_pos)
                    if pred_rate_pos is not None and np.isfinite(float(pred_rate_pos))
                    else float(true_rate_pos)
                )
            ),
            activation_rate_neg=(
                float(true_rate_neg)
                if bool(is_perfect_foresight)
                else (
                    float(pred_rate_neg)
                    if pred_rate_neg is not None and np.isfinite(float(pred_rate_neg))
                    else float(true_rate_neg)
                )
            ),
            da_charge_mw=float(ch_plan),
            da_discharge_mw=float(dis_plan),
            preserve_da_lockbook=bool(allow_da and allow_bem),
        )
        bem_q_pos = 0.0
        bem_q_neg = 0.0
        bem_cap_bids: list[AFRRCapacityBid] = []
        bcm_cap_bids: list[AFRRCapacityBid] = []
        if allow_bem:
            bem_q_pos = self._round_market_bid_down_mw(
                float(bem_guard["submitted_bem_only_pos_mw"]),
                step_mw=self.afrr_step_mw,
                min_mw=self.afrr_min_bid_size_mw,
            )
            bem_q_neg = self._round_market_bid_down_mw(
                float(bem_guard["submitted_bem_only_neg_mw"]),
                step_mw=self.afrr_step_mw,
                min_mw=self.afrr_min_bid_size_mw,
            )

        if ob_pos > 0.0 or ob_neg > 0.0:
            # Capacity already cleared in aFRR BCM: use mandatory obligation.
            cap_bids = []
            if ob_pos > 0.0:
                bcm_cap_bids.append(
                    AFRRCapacityBid(
                        ts=ts,
                        side="pos",
                        quantity_mw=ob_pos,
                        capacity_price_eur_mw=float(
                            obligation_capacity_price_pos_resolved
                            if np.isfinite(obligation_capacity_price_pos_resolved)
                            else 0.0
                        ),
                        energy_price_eur_mwh=_dynamic_afrr_energy_price_with_guard(
                            diag_key="bcm_pos",
                            side="pos",
                            pred_act_price=float(pred_act_pos if not (obligation_energy_pos is not None and np.isfinite(obligation_energy_pos)) else obligation_energy_pos),
                            obligation_mw=ob_pos,
                            activation_headroom_h=self.reserve_activation_headroom_h,
                            q10=float(pred_act_pos_q10) if pred_act_pos_q10 is not None and np.isfinite(pred_act_pos_q10) else None,
                            q50=float(pred_act_pos_q50) if pred_act_pos_q50 is not None and np.isfinite(pred_act_pos_q50) else None,
                            q90=float(pred_act_pos_q90) if pred_act_pos_q90 is not None and np.isfinite(pred_act_pos_q90) else None,
                            true_act_price=float(true_act_pos),
                        ),
                    )
                )
            if ob_neg > 0.0:
                bcm_cap_bids.append(
                    AFRRCapacityBid(
                        ts=ts,
                        side="neg",
                        quantity_mw=ob_neg,
                        capacity_price_eur_mw=float(
                            obligation_capacity_price_neg_resolved
                            if np.isfinite(obligation_capacity_price_neg_resolved)
                            else 0.0
                        ),
                        energy_price_eur_mwh=_dynamic_afrr_energy_price_with_guard(
                            diag_key="bcm_neg",
                            side="neg",
                            pred_act_price=float(pred_act_neg if not (obligation_energy_neg is not None and np.isfinite(obligation_energy_neg)) else obligation_energy_neg),
                            obligation_mw=ob_neg,
                            activation_headroom_h=self.reserve_activation_headroom_h,
                            q10=float(pred_act_neg_q10) if pred_act_neg_q10 is not None and np.isfinite(pred_act_neg_q10) else None,
                            q50=float(pred_act_neg_q50) if pred_act_neg_q50 is not None and np.isfinite(pred_act_neg_q50) else None,
                            q90=float(pred_act_neg_q90) if pred_act_neg_q90 is not None and np.isfinite(pred_act_neg_q90) else None,
                            true_act_price=float(true_act_neg),
                        ),
                    )
                )
            cap_bids.extend(bcm_cap_bids)
            cap_res = self.market_clearing_engine.clear_afrr_capacity(
                bcm_cap_bids,
                true_cap_pos=float(true_cap_pos),
                true_cap_neg=float(true_cap_neg),
            )
            # Enforce already-awarded obligations independently of spot capacity check.
            cap_res = type(cap_res)(
                submitted_pos_mw=ob_pos,
                submitted_neg_mw=ob_neg,
                awarded_pos_mw=ob_pos,
                awarded_neg_mw=ob_neg,
                pos_awarded=ob_pos > 0.0,
                neg_awarded=ob_neg > 0.0,
            )
            bin_payload["submitted_afrr_pos_bin_0_mw"] = float(ob_pos)
            bin_payload["submitted_afrr_neg_bin_0_mw"] = float(ob_neg)
            bin_payload["submitted_afrr_pos_bin_0_price_eur_mw"] = float(
                obligation_capacity_price_pos_resolved
                if ob_pos > 1e-12 and np.isfinite(obligation_capacity_price_pos_resolved)
                else 0.0
            )
            bin_payload["submitted_afrr_neg_bin_0_price_eur_mw"] = float(
                obligation_capacity_price_neg_resolved
                if ob_neg > 1e-12 and np.isfinite(obligation_capacity_price_neg_resolved)
                else 0.0
            )
            bin_payload["executed_afrr_cap_pos_bin_0_mw"] = float(ob_pos)
            bin_payload["executed_afrr_cap_neg_bin_0_mw"] = float(ob_neg)
            bin_payload["executed_afrr_cap_pos_bin_0_price_eur_mw"] = float(
                obligation_capacity_price_pos_resolved
                if ob_pos > 1e-12 and np.isfinite(obligation_capacity_price_pos_resolved)
                else 0.0
            )
            bin_payload["executed_afrr_cap_neg_bin_0_price_eur_mw"] = float(
                obligation_capacity_price_neg_resolved
                if ob_neg > 1e-12 and np.isfinite(obligation_capacity_price_neg_resolved)
                else 0.0
            )
        else:
            # No BCM obligation for this delivery hour.
            # Explicit BEM-only participation uses independent planned BEM volumes.
            # In the generic aFRR strategy, current-hour reserve variables cannot
            # represent newly awarded BCM capacity unless a lockbook obligation
            # exists. They are treated as free BEM volume, but only after the
            # settlement-SoC BEM guard above has capped them.
            cap_bids: list[AFRRCapacityBid] = []
            q_pos = float(bem_q_pos)
            q_neg = float(bem_q_neg)
            bin_payload["submitted_afrr_pos_bin_0_mw"] = float(q_pos)
            bin_payload["submitted_afrr_neg_bin_0_mw"] = float(q_neg)
            bin_payload["submitted_afrr_pos_bin_0_price_eur_mw"] = 0.0
            bin_payload["submitted_afrr_neg_bin_0_price_eur_mw"] = 0.0
            if q_pos > 0.0:
                bem_cap_bids.append(
                    AFRRCapacityBid(
                        ts=ts,
                        side="pos",
                        quantity_mw=float(q_pos),
                        capacity_price_eur_mw=0.0,
                        energy_price_eur_mwh=float(pred_act_pos),
                    )
                )
            if q_neg > 0.0:
                bem_cap_bids.append(
                    AFRRCapacityBid(
                        ts=ts,
                        side="neg",
                        quantity_mw=float(q_neg),
                        capacity_price_eur_mw=0.0,
                        energy_price_eur_mwh=float(pred_act_neg),
                    )
                )
            cap_bids.extend(bem_cap_bids)
            submitted_pos = float(sum(float(b.quantity_mw) for b in cap_bids if b.side == "pos"))
            submitted_neg = float(sum(float(b.quantity_mw) for b in cap_bids if b.side == "neg"))
            cap_res = AFRRCapacityClearingResult(
                submitted_pos_mw=submitted_pos,
                submitted_neg_mw=submitted_neg,
                awarded_pos_mw=0.0,
                awarded_neg_mw=0.0,
                pos_awarded=False,
                neg_awarded=False,
            )
            # T-25 dynamic energy update prior to activation merit-order check.
            cap_bids = [
                AFRRCapacityBid(
                    ts=b.ts,
                    side=b.side,
                    quantity_mw=b.quantity_mw,
                    capacity_price_eur_mw=b.capacity_price_eur_mw,
                    energy_price_eur_mwh=_dynamic_afrr_energy_price_with_guard(
                        diag_key=f"bem_{b.side}",
                        side=b.side,
                        pred_act_price=float(pred_act_pos if b.side == "pos" else pred_act_neg),
                        obligation_mw=float(b.quantity_mw),
                        activation_headroom_h=self.bem_activation_headroom_h,
                        q10=float(pred_act_pos_q10) if (b.side == "pos" and pred_act_pos_q10 is not None and np.isfinite(pred_act_pos_q10)) else (float(pred_act_neg_q10) if (b.side == "neg" and pred_act_neg_q10 is not None and np.isfinite(pred_act_neg_q10)) else None),
                        q50=float(pred_act_pos_q50) if (b.side == "pos" and pred_act_pos_q50 is not None and np.isfinite(pred_act_pos_q50)) else (float(pred_act_neg_q50) if (b.side == "neg" and pred_act_neg_q50 is not None and np.isfinite(pred_act_neg_q50)) else None),
                        q90=float(pred_act_pos_q90) if (b.side == "pos" and pred_act_pos_q90 is not None and np.isfinite(pred_act_pos_q90)) else (float(pred_act_neg_q90) if (b.side == "neg" and pred_act_neg_q90 is not None and np.isfinite(pred_act_neg_q90)) else None),
                        true_act_price=float(true_act_pos if b.side == "pos" else true_act_neg),
                    ),
                )
                for b in cap_bids
            ]
            bem_cap_bids = list(cap_bids)
        if ob_pos > 0.0 or ob_neg > 0.0:
            if bem_q_pos > 0.0:
                bem_cap_bids.append(
                    AFRRCapacityBid(
                        ts=ts,
                        side="pos",
                        quantity_mw=float(bem_q_pos),
                        capacity_price_eur_mw=0.0,
                        energy_price_eur_mwh=_dynamic_afrr_energy_price_with_guard(
                            diag_key="bem_pos",
                            side="pos",
                            pred_act_price=float(pred_act_pos),
                            obligation_mw=float(bem_q_pos),
                            activation_headroom_h=self.bem_activation_headroom_h,
                            q10=float(pred_act_pos_q10) if pred_act_pos_q10 is not None and np.isfinite(pred_act_pos_q10) else None,
                            q50=float(pred_act_pos_q50) if pred_act_pos_q50 is not None and np.isfinite(pred_act_pos_q50) else None,
                            q90=float(pred_act_pos_q90) if pred_act_pos_q90 is not None and np.isfinite(pred_act_pos_q90) else None,
                            true_act_price=float(true_act_pos),
                        ),
                    )
                )
            if bem_q_neg > 0.0:
                bem_cap_bids.append(
                    AFRRCapacityBid(
                        ts=ts,
                        side="neg",
                        quantity_mw=float(bem_q_neg),
                        capacity_price_eur_mw=0.0,
                        energy_price_eur_mwh=_dynamic_afrr_energy_price_with_guard(
                            diag_key="bem_neg",
                            side="neg",
                            pred_act_price=float(pred_act_neg),
                            obligation_mw=float(bem_q_neg),
                            activation_headroom_h=self.bem_activation_headroom_h,
                            q10=float(pred_act_neg_q10) if pred_act_neg_q10 is not None and np.isfinite(pred_act_neg_q10) else None,
                            q50=float(pred_act_neg_q50) if pred_act_neg_q50 is not None and np.isfinite(pred_act_neg_q50) else None,
                            q90=float(pred_act_neg_q90) if pred_act_neg_q90 is not None and np.isfinite(pred_act_neg_q90) else None,
                            true_act_price=float(true_act_neg),
                        ),
                    )
                )
            cap_bids.extend(bem_cap_bids)
        if allow_da and da_execution_policy == "price_taker":
            da_bids = []
            if ch_plan > 0.0:
                da_bids.append(
                    DABid(
                        ts=ts,
                        side="buy",
                        quantity_mw=float(ch_plan),
                        price_eur_mwh=float(pred_da_price),
                        mode="price_taker",
                        reason="price_taker_lockbook",
                    )
                )
            if dis_plan > 0.0:
                da_bids.append(
                    DABid(
                        ts=ts,
                        side="sell",
                        quantity_mw=float(dis_plan),
                        price_eur_mwh=float(pred_da_price),
                        mode="price_taker",
                        reason="price_taker_lockbook",
                    )
                )
        elif allow_da:
            da_bids = self.bid_builder.build_da_bids_from_plan(
                ts=ts,
                planned_charge_mw=ch_plan,
                planned_discharge_mw=dis_plan,
                obligation_pos_mw=ob_pos if ob_pos > 0.0 else cap_res.awarded_pos_mw,
                obligation_neg_mw=ob_neg if ob_neg > 0.0 else cap_res.awarded_neg_mw,
                pred_da_price=float(pred_da_price),
                pred_da_price_p05=float(pred_da_price_p05) if pred_da_price_p05 is not None and np.isfinite(pred_da_price_p05) else None,
                pred_da_price_p10=float(pred_da_price_p10) if pred_da_price_p10 is not None and np.isfinite(pred_da_price_p10) else None,
                pred_da_price_p50=float(pred_da_price_p50) if pred_da_price_p50 is not None and np.isfinite(pred_da_price_p50) else float(pred_da_price),
                pred_da_price_p90=float(pred_da_price_p90) if pred_da_price_p90 is not None and np.isfinite(pred_da_price_p90) else None,
                pred_da_price_p95=float(pred_da_price_p95) if pred_da_price_p95 is not None and np.isfinite(pred_da_price_p95) else None,
                is_perfect_foresight=is_perfect_foresight,
            )
        else:
            da_bids = []
        if ob_pos > 0.0 or ob_neg > 0.0:
            # Phase 2 DA restriction: available power after aFRR capacity lock.
            available_da = max(0.0, self.p_max_mw - max(ob_pos, ob_neg))
            capped_da_bids = []
            for b in da_bids:
                q = min(float(b.quantity_mw), available_da)
                if q <= 0.0:
                    continue
                capped_da_bids.append(type(b)(ts=b.ts, side=b.side, quantity_mw=q, price_eur_mwh=b.price_eur_mwh, mode=b.mode, reason=b.reason))
            da_bids = capped_da_bids
        if da_execution_policy == "price_taker":
            da_bids = [
                type(b)(
                    ts=b.ts,
                    side=b.side,
                    quantity_mw=b.quantity_mw,
                    price_eur_mwh=b.price_eur_mwh,
                    mode="price_taker",
                    reason=b.reason,
                )
                for b in da_bids
            ]
        da_res = self.market_clearing_engine.clear_da(
            da_bids,
            true_da_price=float(true_da_price),
        )
        submitted_da_buy_prices = [float(b.price_eur_mwh) for b in da_bids if b.side == "buy" and float(b.quantity_mw) > 0.0]
        submitted_da_sell_prices = [float(b.price_eur_mwh) for b in da_bids if b.side == "sell" and float(b.quantity_mw) > 0.0]
        submitted_da_buy_price = float(np.mean(submitted_da_buy_prices)) if submitted_da_buy_prices else float("nan")
        submitted_da_sell_price = float(np.mean(submitted_da_sell_prices)) if submitted_da_sell_prices else float("nan")
        da_buy_limit_quantile = str(getattr(self.bid_builder, "da_buy_limit_quantile", "p50")).lower()
        da_sell_limit_quantile = str(getattr(self.bid_builder, "da_sell_limit_quantile", "p50")).lower()
        da_limit_quantile = da_buy_limit_quantile if ch_plan > 1e-9 else (da_sell_limit_quantile if dis_plan > 1e-9 else "")
        da_selected_forecast_column = "pred_da_price"
        da_limit_source_column = (
            da_selected_forecast_column
            if da_limit_quantile == "p50"
            else (f"{da_selected_forecast_column}_{da_limit_quantile}" if da_limit_quantile else "")
        )
        # aFRR BEM (balancing energy market):
        # - mandatory BEM activation bids are derived from already-awarded BCM capacity
        # - free BEM-only bids are derived from explicit optimizer variables
        # - activation clearing must use BEM activation bids, not BCM capacity bids
        bem_submitted_pos_mw = float(sum(float(b.quantity_mw) for b in bem_cap_bids if b.side == "pos"))
        bem_submitted_neg_mw = float(sum(float(b.quantity_mw) for b in bem_cap_bids if b.side == "neg"))
        bem_activation_bids = list(bcm_cap_bids) + list(bem_cap_bids)
        act_cap_res = AFRRCapacityClearingResult(
            submitted_pos_mw=float(max(0.0, ob_pos) + bem_submitted_pos_mw),
            submitted_neg_mw=float(max(0.0, ob_neg) + bem_submitted_neg_mw),
            awarded_pos_mw=float(max(0.0, ob_pos) + bem_submitted_pos_mw),
            awarded_neg_mw=float(max(0.0, ob_neg) + bem_submitted_neg_mw),
            pos_awarded=float(max(0.0, ob_pos) + bem_submitted_pos_mw) > 1e-12,
            neg_awarded=float(max(0.0, ob_neg) + bem_submitted_neg_mw) > 1e-12,
        )
        act_res = self.market_clearing_engine.clear_afrr_activation(
            bem_activation_bids,
            act_cap_res,
            true_act_pos=float(true_act_pos),
            true_act_neg=float(true_act_neg),
            true_rate_pos=float(true_rate_pos),
            true_rate_neg=float(true_rate_neg),
        )
        ch_exec = float(da_res.executed_buy_mw)
        dis_exec = float(da_res.executed_sell_mw)
        res_pos_exec = float(act_cap_res.awarded_pos_mw) if bool(act_res.pos_accepted) else float(max(0.0, ob_pos))
        res_neg_exec = float(act_cap_res.awarded_neg_mw) if bool(act_res.neg_accepted) else float(max(0.0, ob_neg))

        def _mean_bcm_capacity_bid_price(side: str, awarded_mw: float) -> float:
            if float(awarded_mw) <= 1e-12:
                return 0.0
            obligation_price = (
                obligation_capacity_price_pos
                if side == "pos"
                else obligation_capacity_price_neg
            )
            if obligation_price is not None:
                try:
                    obligation_price_f = float(obligation_price)
                except (TypeError, ValueError):
                    obligation_price_f = float("nan")
                if np.isfinite(obligation_price_f) and abs(obligation_price_f) > 1e-12:
                    return float(obligation_price_f)
            bids_for_side = [
                b
                for b in bcm_cap_bids
                if b.side == side and float(b.quantity_mw) > 1e-12
            ]
            if not bids_for_side:
                fallback_price = (
                    obligation_capacity_price_pos_resolved
                    if side == "pos"
                    else obligation_capacity_price_neg_resolved
                )
                return float(fallback_price) if np.isfinite(fallback_price) else 0.0
            qty = float(sum(float(b.quantity_mw) for b in bids_for_side))
            value = float(
                sum(float(b.quantity_mw) * float(b.capacity_price_eur_mw) for b in bids_for_side)
            )
            mean_price = float(value / max(qty, 1e-12))
            if np.isfinite(mean_price) and abs(mean_price) > 1e-12:
                return float(mean_price)
            fallback_price = (
                obligation_capacity_price_pos_resolved
                if side == "pos"
                else obligation_capacity_price_neg_resolved
            )
            return float(fallback_price) if np.isfinite(fallback_price) else 0.0

        # BCM capacity remuneration is pay-as-bid on already awarded/locked MW.
        # The activation price is only used later by BEM activation clearing.
        cap_bid_pos_settlement = (
            _mean_bcm_capacity_bid_price("pos", res_pos_exec)
            if ((ob_pos > 0.0 or ob_neg > 0.0) and res_pos_exec > 1e-12)
            else 0.0
        )
        cap_bid_neg_settlement = (
            _mean_bcm_capacity_bid_price("neg", res_neg_exec)
            if ((ob_pos > 0.0 or ob_neg > 0.0) and res_neg_exec > 1e-12)
            else 0.0
        )
        bcm_capacity_price_missing_with_awarded_mw = float(
            (res_pos_exec > 1e-12 and abs(float(cap_bid_pos_settlement)) <= 1e-12)
            or (res_neg_exec > 1e-12 and abs(float(cap_bid_neg_settlement)) <= 1e-12)
        )
        bcm_capacity_price_lost_before_settlement = float(
            bcm_capacity_price_missing_with_awarded_mw > 0.5
            and (ob_pos > 1e-12 or ob_neg > 1e-12)
        )
        rate_pos_exec = float(act_res.executed_rate_pos)
        rate_neg_exec = float(act_res.executed_rate_neg)
        def _activation_bid_clears(bid: AFRRCapacityBid) -> bool:
            if bid.side == "pos":
                return float(bid.energy_price_eur_mwh) <= float(true_act_pos)
            if self.forecast_value_mode == "canonical_economic":
                return float(bid.energy_price_eur_mwh) <= float(true_act_neg)
            return float(bid.energy_price_eur_mwh) >= float(true_act_neg)

        bcm_source_pos_mw = float(sum(float(b.quantity_mw) for b in bcm_cap_bids if b.side == "pos" and _activation_bid_clears(b)))
        bcm_source_neg_mw = float(sum(float(b.quantity_mw) for b in bcm_cap_bids if b.side == "neg" and _activation_bid_clears(b)))
        bem_source_pos_mw = float(sum(float(b.quantity_mw) for b in bem_cap_bids if b.side == "pos" and _activation_bid_clears(b)))
        bem_source_neg_mw = float(sum(float(b.quantity_mw) for b in bem_cap_bids if b.side == "neg" and _activation_bid_clears(b)))
        if not bool(act_res.pos_accepted):
            bcm_source_pos_mw = 0.0
            bem_source_pos_mw = 0.0
        if not bool(act_res.neg_accepted):
            bcm_source_neg_mw = 0.0
            bem_source_neg_mw = 0.0
        # Fill per-bin executed settlement transparency (capacity + activated energy).
        for b in range(n_bins):
            s_pos = float(bin_payload.get(f"submitted_afrr_pos_bin_{b}_mw", 0.0))
            s_neg = float(bin_payload.get(f"submitted_afrr_neg_bin_{b}_mw", 0.0))
            p_pos = float(bin_payload.get(f"submitted_afrr_pos_bin_{b}_price_eur_mw", 0.0))
            p_neg = float(bin_payload.get(f"submitted_afrr_neg_bin_{b}_price_eur_mw", 0.0))
            if ob_pos > 0.0 or ob_neg > 0.0:
                aw_pos = s_pos if (s_pos > 0.0 and bool(cap_res.pos_awarded)) else 0.0
                aw_neg = s_neg if (s_neg > 0.0 and bool(cap_res.neg_awarded)) else 0.0
            else:
                aw_pos = 0.0
                aw_neg = 0.0
            bin_payload[f"executed_afrr_cap_pos_bin_{b}_mw"] = float(aw_pos)
            bin_payload[f"executed_afrr_cap_neg_bin_{b}_mw"] = float(aw_neg)
            bin_payload[f"executed_afrr_cap_pos_bin_{b}_price_eur_mw"] = float(p_pos if aw_pos > 0.0 else 0.0)
            bin_payload[f"executed_afrr_cap_neg_bin_{b}_price_eur_mw"] = float(p_neg if aw_neg > 0.0 else 0.0)
            if ob_pos > 0.0 or ob_neg > 0.0:
                act_base_pos = aw_pos
                act_base_neg = aw_neg
            else:
                act_base_pos = s_pos
                act_base_neg = s_neg
            act_mw_pos = float(act_base_pos * rate_pos_exec if act_res.pos_accepted else 0.0)
            act_mw_neg = float(act_base_neg * rate_neg_exec if act_res.neg_accepted else 0.0)
            bin_payload[f"executed_afrr_act_pos_bin_{b}_mw"] = float(act_mw_pos)
            bin_payload[f"executed_afrr_act_neg_bin_{b}_mw"] = float(act_mw_neg)
            bin_payload[f"executed_afrr_act_pos_bin_{b}_price_eur_mwh"] = float(true_act_pos if act_mw_pos > 0.0 else 0.0)
            bin_payload[f"executed_afrr_act_neg_bin_{b}_price_eur_mwh"] = float(true_act_neg if act_mw_neg > 0.0 else 0.0)
        da_buy_accepted = bool(da_res.buy_accepted)
        da_sell_accepted = bool(da_res.sell_accepted)
        da_submitted = bool(float(da_res.submitted_buy_mw) > 1e-12 or float(da_res.submitted_sell_mw) > 1e-12)
        da_cleared = bool(da_buy_accepted or da_sell_accepted)
        cap_pos_awarded = bool(cap_res.pos_awarded)
        cap_neg_awarded = bool(cap_res.neg_awarded)
        act_pos_accepted = bool(act_res.pos_accepted)
        act_neg_accepted = bool(act_res.neg_accepted)
        is_bcm_obligation_hour = bool((ob_pos > 0.0) or (ob_neg > 0.0))
        if ob_pos > 1e-12 and ob_neg > 1e-12:
            bcm_direction = "both"
        elif ob_pos > 1e-12:
            bcm_direction = "pos"
        elif ob_neg > 1e-12:
            bcm_direction = "neg"
        else:
            bcm_direction = "none"
        # BEM-only is a source-specific stream and may coexist with BCM obligations.
        bem_only_submitted_pos_mw = float(bem_submitted_pos_mw)
        bem_only_submitted_neg_mw = float(bem_submitted_neg_mw)
        bem_only_executed_pos_mw = float(bem_source_pos_mw)
        bem_only_executed_neg_mw = float(bem_source_neg_mw)
        bem_only_executed_pos_mwh = float(bem_only_executed_pos_mw * rate_pos_exec * self.dt_h)
        bem_only_executed_neg_mwh = float(bem_only_executed_neg_mw * rate_neg_exec * self.dt_h)
        bcm_linked_pos_activation_mwh = float(bcm_source_pos_mw * rate_pos_exec * self.dt_h)
        bcm_linked_neg_activation_mwh = float(bcm_source_neg_mw * rate_neg_exec * self.dt_h)
        true_act_neg_provider_value = float(self._neg_activation_provider_value(float(true_act_neg)))
        bem_only_pos_activation_revenue_eur = float(bem_only_executed_pos_mwh * true_act_pos)
        bem_only_neg_activation_revenue_eur = float(bem_only_executed_neg_mwh * true_act_neg_provider_value)
        bem_only_activation_revenue_eur = float(
            bem_only_pos_activation_revenue_eur + bem_only_neg_activation_revenue_eur
        )
        bcm_linked_pos_activation_revenue_eur = float(bcm_linked_pos_activation_mwh * true_act_pos)
        bcm_linked_neg_activation_revenue_eur = float(bcm_linked_neg_activation_mwh * true_act_neg_provider_value)
        bcm_linked_activation_revenue_eur = float(
            bcm_linked_pos_activation_revenue_eur + bcm_linked_neg_activation_revenue_eur
        )
        bem_pos_activation_mwh = float(bcm_linked_pos_activation_mwh + bem_only_executed_pos_mwh)
        bem_neg_activation_mwh = float(bcm_linked_neg_activation_mwh + bem_only_executed_neg_mwh)
        bem_activation_revenue_eur = float(
            bcm_linked_activation_revenue_eur + bem_only_activation_revenue_eur
        )
        bem_total_bid_volume_pos_mw = float(max(0.0, ob_pos) + bem_only_submitted_pos_mw)
        bem_total_bid_volume_neg_mw = float(max(0.0, ob_neg) + bem_only_submitted_neg_mw)
        bem_total_bid_volume_mw = float(max(bem_total_bid_volume_pos_mw, bem_total_bid_volume_neg_mw))
        has_bem_bid_volume = bool(bem_total_bid_volume_mw > 1e-12)
        energy_prices = [
            float(v)
            for v in (obligation_energy_pos, obligation_energy_neg)
            if v is not None and np.isfinite(v)
        ]
        mean_energy_price = float(np.mean(energy_prices)) if energy_prices else float("nan")
        bcm_activation_bid_price_pos = float(
            np.mean([float(b.energy_price_eur_mwh) for b in bcm_cap_bids if b.side == "pos"])
        ) if any(b.side == "pos" for b in bcm_cap_bids) else 0.0
        bcm_activation_bid_price_neg = float(
            np.mean([float(b.energy_price_eur_mwh) for b in bcm_cap_bids if b.side == "neg"])
        ) if any(b.side == "neg" for b in bcm_cap_bids) else 0.0
        bem_activation_bid_price_pos = float(
            np.mean([float(b.energy_price_eur_mwh) for b in bem_activation_bids if b.side == "pos"])
        ) if any(b.side == "pos" for b in bem_activation_bids) else 0.0
        bem_activation_bid_price_neg = float(
            np.mean([float(b.energy_price_eur_mwh) for b in bem_activation_bids if b.side == "neg"])
        ) if any(b.side == "neg" for b in bem_activation_bids) else 0.0
        bcm_capacity_bid_price_pos = _mean_bcm_capacity_bid_price("pos", ob_pos)
        bcm_capacity_bid_price_neg = _mean_bcm_capacity_bid_price("neg", ob_neg)
        if not allow_bcm:
            bcm_zero_reason = "bcm_disabled"
        elif (ob_pos > 1e-12 or ob_neg > 1e-12) and (bcm_source_pos_mw <= 1e-12 and bcm_source_neg_mw <= 1e-12):
            bcm_zero_reason = "clearing_failed"
        elif ob_pos <= 1e-12 and ob_neg <= 1e-12 and res_pos_plan <= 1e-12 and res_neg_plan <= 1e-12:
            bcm_zero_reason = "no_bcm_candidate"
        elif ob_pos <= 1e-12 and ob_neg <= 1e-12:
            bcm_zero_reason = "outside_bcm_gate"
        else:
            bcm_zero_reason = "none"

        def _guard_value(key: str, field: str, default: float | str) -> float | str:
            diag = activation_guard_diags.get(key, {})
            return diag.get(field, default)

        active_guard_key = "none"
        if ob_pos > 1e-12:
            active_guard_key = "bcm_pos"
        elif ob_neg > 1e-12:
            active_guard_key = "bcm_neg"
        elif bem_only_submitted_pos_mw > 1e-12:
            active_guard_key = "bem_pos"
        elif bem_only_submitted_neg_mw > 1e-12:
            active_guard_key = "bem_neg"

