                            "optimizer_validation_trial_pos_mw",
                            "optimizer_validation_trial_neg_mw",
                            "candidate_unrecoverable_physical_diagnostics_present",
                            "unrecoverable_without_physical_diagnostics",
                            "best_nonzero_failed_retry_factor",
