                    precommit_audit_by_ts.setdefault("precommit_clamp_applied", {})[tsu] = float(precommit_applied)
                    precommit_audit_by_ts.setdefault("precommit_clamp_reason", {})[tsu] = str(precommit_clamp_reason)
