        def _pf_failure_status(exc: BaseException) -> str:
            msg = str(exc).lower()
            if "status 15" in msg or ("unknown" in msg and "feasible" in msg):
                return "unknown_feasible"
            if "not set" in msg:
                return "not_set"
            if "infeasible" in msg:
                return "infeasible"
            return "solver_failed"

        def _empty_pf_frame(prefix: str) -> pd.DataFrame:
            ts = pd.to_datetime(df[colmap.timestamp], utc=True, errors="coerce") if colmap.timestamp in df.columns else pd.Series(dtype="datetime64[ns, UTC]")
            out = pd.DataFrame({colmap.timestamp: ts})
            for suffix in (
                "pnl_eur",
                "net_cashflow_eur",
                "soc_mwh",
                "revenue_da_eur",
                "cost_da_eur",
                "revenue_id_eur",
                "cost_id_eur",
                "revenue_capacity_eur",
                "revenue_activation_eur",
                "bcm_linked_activation_revenue_eur",
                "bem_only_activation_revenue_eur",
                "degradation_cost_eur",
                "transaction_cost_eur",
                "aux_cost_eur",
                "penalty_eur",
                "act_pos_mwh",
                "act_neg_mwh",
            ):
                out[f"{prefix}_{suffix}"] = np.nan
            return out

        def _rename_realized_frame(frame: pd.DataFrame, prefix: str) -> pd.DataFrame:
            if frame.empty:
                return _empty_pf_frame(prefix)
            return frame.rename(
                columns={
                    c: c.replace("real_", f"{prefix}_", 1)
                    for c in frame.columns
                    if c.startswith("real_")
                }
            )

        def _sum_first_available_mwh(
            frame: pd.DataFrame,
            specs: list[tuple[str, bool]],
        ) -> float:
            """Return the first available volume sum; MW columns are converted with dt_h."""
            if frame is None or frame.empty:
                return 0.0
            for col_name, is_mw in specs:
                if col_name in frame.columns:
                    vals = pd.to_numeric(frame[col_name], errors="coerce").fillna(0.0)
                    total = float(vals.sum())
                    if bool(is_mw):
                        total *= float(self.dt_h)
                    return float(total)
            return 0.0

        def _build_no_market_terminal_id_incumbent(path_df: pd.DataFrame) -> tuple[pd.DataFrame, dict[str, float | str]]:
            """Settle a no-market incumbent with only technical ID to satisfy terminal SoC."""
            ts = pd.to_datetime(path_df[colmap.timestamp], utc=True, errors="coerce")
            dispatch_zero = pd.DataFrame(
                {
                    colmap.timestamp: ts,
                    "charge_mw": np.zeros(len(path_df), dtype=float),
                    "discharge_mw": np.zeros(len(path_df), dtype=float),
                    "reserve_pos_mw": np.zeros(len(path_df), dtype=float),
                    "reserve_neg_mw": np.zeros(len(path_df), dtype=float),
                    "bem_only_pos_mw": np.zeros(len(path_df), dtype=float),
                    "bem_only_neg_mw": np.zeros(len(path_df), dtype=float),
                    "id_charge_mw": np.zeros(len(path_df), dtype=float),
                    "id_discharge_mw": np.zeros(len(path_df), dtype=float),
                    "id_recourse_reason": np.full(len(path_df), "none", dtype=object),
                    "optimization_error_code": np.full(len(path_df), "ok", dtype=object),
                    "optimizer_fallback_used": np.zeros(len(path_df), dtype=float),
                }
            )
            settled = pd.DataFrame()
            final_soc = float(self.soc_init)
            no_id_final_soc = float(self.soc_init)
            iteration_count = 0
            # Iterating handles ID-efficiency conversion plus auxiliary losses
            # that appear only after the ID charge is scheduled.
            for _attempt in range(8):
                iteration_count = int(_attempt) + 1
                settled = self.settle_dispatch(
                    path_df,
                    dispatch_zero,
                    colmap,
                    predicted_settlement=False,
                    apply_market_clearing=True,
                    perfect_foresight_mode=True,
                )
                if not settled.empty and "real_soc_mwh" in settled.columns:
                    soc_vals_iter = pd.to_numeric(settled["real_soc_mwh"], errors="coerce").dropna()
                    if not soc_vals_iter.empty:
                        final_soc = float(soc_vals_iter.iloc[-1])
                if _attempt == 0:
                    no_id_final_soc = float(final_soc)
                shortfall = max(0.0, float(self.soc_target_end) - final_soc)
                if shortfall <= 1e-6 or dispatch_zero.empty:
                    break
                remaining_grid_mwh = shortfall / max(float(self.eta_in), 1e-12)
                # Allocate from the latest hour backwards so the incumbent does
                # not take earlier economic exposure than needed.
                for idx in reversed(dispatch_zero.index.to_list()):
                    residual_mw = max(0.0, float(self.p_max_mw) - float(dispatch_zero.at[idx, "id_charge_mw"]))
                    add_grid_mwh = min(remaining_grid_mwh, residual_mw * float(self.dt_h))
                    if add_grid_mwh <= 1e-12:
                        continue
                    dispatch_zero.at[idx, "id_charge_mw"] = float(dispatch_zero.at[idx, "id_charge_mw"]) + (
                        add_grid_mwh / max(float(self.dt_h), 1e-12)
                    )
                    dispatch_zero.at[idx, "id_recourse_reason"] = "terminal_soc_recovery"
                    remaining_grid_mwh -= add_grid_mwh
                    if remaining_grid_mwh <= 1e-12:
                        break
            scheduled_grid_mwh = float(
                pd.to_numeric(dispatch_zero["id_charge_mw"], errors="coerce").fillna(0.0).sum() * self.dt_h
            )
            scheduled_internal_mwh = float(scheduled_grid_mwh * self.eta_in)
            projection_diag = self._project_terminal_soc_with_known_flows(
                current_soc_mwh=float(self.soc_init),
                remaining_aux_losses_mwh=max(0.0, float(self.soc_init) - float(no_id_final_soc)),
                existing_scheduled_id_internal_mwh=0.0,
            )
            recovery_diag = self._schedule_terminal_id_recovery(
                projected_terminal_soc_without_new_id_mwh=float(no_id_final_soc),
                current_soc_mwh=float(self.soc_init),
                terminal_soc_target_mwh=float(self.soc_target_end),
                residual_charge_mw=float(self.p_max_mw) * max(len(dispatch_zero), 1),
                terminal_soc_safety_margin_mwh=0.0,
            )
            recovery_diag["terminal_soc_id_recourse_scheduled_grid_mwh"] = float(scheduled_grid_mwh)
            recovery_diag["terminal_soc_id_recourse_scheduled_internal_mwh"] = float(scheduled_internal_mwh)
            recovery_diag["projected_terminal_soc_with_new_id_mwh"] = float(final_soc)
            recovery_diag["terminal_soc_recovery_iteration_count"] = float(iteration_count)
            recovery_diag["terminal_soc_recovery_feasible"] = float(final_soc + 1e-6 >= float(self.soc_target_end))
            recovery_diag["terminal_soc_not_recoverable_with_id"] = float(final_soc + 1e-6 < float(self.soc_target_end))
            recovery_diag["terminal_soc_not_recoverable_reason"] = (
                "none" if final_soc + 1e-6 >= float(self.soc_target_end) else "insufficient_remaining_id_capacity"
            )
            for k, v in {**projection_diag, **recovery_diag}.items():
                dispatch_zero[k] = v
            # Re-settle after attaching diagnostics so selected global PF
            # hourly columns are atomically aligned with the incumbent path.
            settled = self.settle_dispatch(
                path_df,
                dispatch_zero,
                colmap,
                predicted_settlement=False,
                apply_market_clearing=True,
                perfect_foresight_mode=True,
            )
            final_soc = (
                float(pd.to_numeric(settled["real_soc_mwh"], errors="coerce").dropna().iloc[-1])
                if not settled.empty and "real_soc_mwh" in settled.columns and not pd.to_numeric(settled["real_soc_mwh"], errors="coerce").dropna().empty
                else float(self.soc_init)
            )
            return settled, {
                "final_soc_mwh": float(final_soc),
                "terminal_shortfall_mwh": float(max(0.0, float(self.soc_target_end) - final_soc)),
                "id_buy_mwh": float(scheduled_grid_mwh),
                "feasible": float(final_soc + 1e-6 >= float(self.soc_target_end)),
            }

        def _terminal_adjustment_value(soc_final_mwh: float, term_price_eur_mwh: float) -> float:
            shortfall_mwh = max(0.0, float(self.soc_target_end) - float(soc_final_mwh))
            surplus_mwh = max(0.0, float(soc_final_mwh) - float(self.soc_target_end))
            repair_cost_eur = (shortfall_mwh / max(self.eta_in, 1e-12)) * float(term_price_eur_mwh)
            liquidation_revenue_eur = (surplus_mwh * self.eta_out) * float(term_price_eur_mwh)
            return float(liquidation_revenue_eur - repair_cost_eur)

        def _component_pnl_for_realized_frame(frame: pd.DataFrame, prefix: str) -> float:
            pnl_col = f"{prefix}_pnl_eur"
            if frame.empty or pnl_col not in frame.columns:
                return float("nan")
            return float(pd.to_numeric(frame[pnl_col], errors="coerce").fillna(0.0).sum())

        def _pnl_total_for_realized_frame(frame: pd.DataFrame, prefix: str, term_price_eur_mwh: float) -> float:
            soc_col = f"{prefix}_soc_mwh"
            pnl_raw = _component_pnl_for_realized_frame(frame, prefix)
            if not np.isfinite(float(pnl_raw)):
                return float("nan")
            soc_vals = (
                pd.to_numeric(frame[soc_col], errors="coerce").dropna()
                if soc_col in frame.columns
                else pd.Series(dtype=float)
            )
            final_soc = float(soc_vals.iloc[-1]) if not soc_vals.empty else float(self.soc_init)
            return float(pnl_raw + _terminal_adjustment_value(final_soc, term_price_eur_mwh))

        def _reportable_pf_timestamps() -> pd.Series:
            for frame in (real, naive_real, perfect_foresight_df):
                if frame is not None and not frame.empty and colmap.timestamp in frame.columns:
                    ts = pd.to_datetime(frame[colmap.timestamp], utc=True, errors="coerce").dropna()
                    if not ts.empty:
                        return ts.drop_duplicates().reset_index(drop=True)
            return pd.Series(dtype="datetime64[ns, UTC]")

        def _align_pf_candidate_to_reportable_horizon(frame: pd.DataFrame) -> tuple[pd.DataFrame, float, str]:
            expected_ts = _reportable_pf_timestamps()
            if frame is None or frame.empty:
                return pd.DataFrame(), float(len(expected_ts)), "empty_frame"
            if expected_ts.empty:
                return frame.copy(), 0.0, "none"
            if colmap.timestamp not in frame.columns:
                return frame.copy(), float(len(expected_ts)), "missing_timestamp_column"
            candidate = frame.copy()
            candidate_ts = pd.to_datetime(candidate[colmap.timestamp], utc=True, errors="coerce")
            expected_set = set(expected_ts.tolist())
            candidate_set = set(candidate_ts.dropna().drop_duplicates().tolist())
            missing = [ts for ts in expected_ts.tolist() if ts not in candidate_set]
            aligned = candidate.loc[candidate_ts.isin(expected_set)].copy()
            if missing:
                first_missing = pd.Timestamp(missing[0]).isoformat()
                return aligned, float(len(missing)), f"missing_expected_timestamps:first={first_missing}"
            return aligned, 0.0, "none"

        def _solver_failure_diag_since(start_idx: int) -> dict[str, float | str]:
            rows = self._solver_failure_diagnostics[start_idx:]
            if not rows:
                return {
                    "timestamp_utc": "",
                    "status": "",
                    "message": "",
                    "nonfinite_coeff_count": 0.0,
                    "bad_bound_count": 0.0,
                }
            bad_rows = [r for r in rows if float(r.get("solver_success", 0.0) or 0.0) < 0.5]
            row = bad_rows[0] if bad_rows else rows[0]
            return {
                "timestamp_utc": str(row.get("timestamp_utc", "")),
                "status": str(row.get("solver_status", "")),
                "message": str(row.get("solver_message", "")),
                "nonfinite_coeff_count": float(row.get("nonfinite_objective_coeff_count", 0.0) or 0.0),
                "bad_bound_count": float(row.get("bad_bound_count", 0.0) or 0.0),
            }

        def _select_rolling_pf_incumbent(
            *,
            prefix: str,
            solver_frame: pd.DataFrame,
            solver_available: bool,
            terminal_price_eur_mwh: float,
        ) -> dict[str, object]:
            """Select a same-rules rolling PF incumbent without hiding solver failures."""
            no_market_real, no_market_diag = _build_no_market_terminal_id_incumbent(perfect_foresight_df)
            no_market_frame = _rename_realized_frame(no_market_real, prefix)
            realized_frame = _rename_realized_frame(real, prefix)
            solver_frame_aligned, solver_missing_count, solver_align_reason = _align_pf_candidate_to_reportable_horizon(
                solver_frame
            )
            no_market_frame_aligned, no_market_missing_count, no_market_align_reason = (
                _align_pf_candidate_to_reportable_horizon(no_market_frame)
            )
            realized_frame_aligned, realized_missing_count, realized_align_reason = (
                _align_pf_candidate_to_reportable_horizon(realized_frame)
            )
            solver_value = _pnl_total_for_realized_frame(solver_frame_aligned, prefix, terminal_price_eur_mwh)
            no_market_value = _pnl_total_for_realized_frame(no_market_frame_aligned, prefix, terminal_price_eur_mwh)
            realized_value = _pnl_total_for_realized_frame(realized_frame_aligned, prefix, terminal_price_eur_mwh)
            # Candidate totals include the terminal target adjustment. Keep the
            # component-balance diagnostics on the same terminal-inclusive basis.
            solver_component = float(solver_value)
            no_market_component = float(no_market_value)
            realized_component = float(realized_value)

            def _frame_feasibility(
                *,
                frame: pd.DataFrame,
                value: float,
                soc_col: str,
                missing_count: float,
                align_reason: str,
                candidate_available: bool = True,
                extra_required_feasible: bool | None = None,
            ) -> tuple[bool, str]:
                if not bool(candidate_available):
                    return False, "solver_unavailable"
                if frame.empty:
                    return False, "empty_frame"
                if float(missing_count) > 0.0:
                    return False, str(align_reason)
                if not np.isfinite(float(value)):
                    return False, "nonfinite_total_pnl"
                if extra_required_feasible is not None and not bool(extra_required_feasible):
                    return False, "candidate_internal_feasibility_failed"
                if soc_col not in frame.columns:
                    return False, "missing_soc_column"
                vals = (
                    pd.to_numeric(frame[soc_col], errors="coerce").dropna()
                )
                if vals.empty:
                    return False, "missing_final_soc"
                final_soc = float(vals.iloc[-1]) if not vals.empty else float(self.soc_init)
                if final_soc + 1e-6 < float(self.soc_target_end):
                    return False, "terminal_soc_shortfall"
                return True, "none"

            solver_feasible, solver_infeasible_reason = _frame_feasibility(
                frame=solver_frame_aligned,
                value=solver_value,
                soc_col=f"{prefix}_soc_mwh",
                missing_count=solver_missing_count,
                align_reason=solver_align_reason,
                candidate_available=bool(solver_available),
            )
            no_market_feasible, no_market_infeasible_reason = _frame_feasibility(
                frame=no_market_frame_aligned,
                value=no_market_value,
                soc_col=f"{prefix}_soc_mwh",
                missing_count=no_market_missing_count,
                align_reason=no_market_align_reason,
                extra_required_feasible=bool(float(no_market_diag.get("feasible", 0.0)) >= 0.5),
            )
            realized_feasible, realized_infeasible_reason = _frame_feasibility(
                frame=realized_frame_aligned,
                value=realized_value,
                soc_col=f"{prefix}_soc_mwh",
                missing_count=realized_missing_count,
                align_reason=realized_align_reason,
            )
            selected = self._select_highest_feasible_incumbent(
                {
                    "solver": (solver_value, solver_feasible, solver_frame_aligned),
                    "no_market": (no_market_value, no_market_feasible, no_market_frame_aligned),
                    "realized_path": (realized_value, realized_feasible, realized_frame_aligned),
                }
            )
            selected_name = str(selected.get("selected", "none"))
            selected_component = {
                "solver": solver_component,
                "no_market": no_market_component,
                "realized_path": realized_component,
            }.get(selected_name, float("nan"))
            selected_value = float(selected.get("value", float("nan")))
            selected_balance_error = (
                float(selected_value - selected_component)
                if np.isfinite(selected_value) and np.isfinite(float(selected_component))
                else float("nan")
            )
            solver_balance_error = (
                float(solver_value - solver_component)
                if np.isfinite(float(solver_value)) and np.isfinite(float(solver_component))
                else float("nan")
            )
            balance_tol = 1e-6
            expected_count = float(len(_reportable_pf_timestamps()))
            return {
                **selected,
                "solver_solution_eur": float(solver_value),
                "solver_total_pnl_eur": float(solver_value),
                "solver_component_pnl_eur": float(solver_component),
                "solver_pnl_balance_error_eur": float(solver_balance_error),
                "solver_pnl_balance_ok": float(
                    np.isfinite(float(solver_balance_error))
                    and abs(float(solver_balance_error)) <= balance_tol
                ),
                "solver_feasible": float(solver_feasible),
                "no_market_feasible": float(no_market_feasible),
                "realized_path_feasible": float(realized_feasible),
                "solver_infeasible_reason": str(solver_infeasible_reason),
                "no_market_infeasible_reason": str(no_market_infeasible_reason),
                "realized_path_infeasible_reason": str(realized_infeasible_reason),
                "expected_row_count": float(expected_count),
                "solver_row_count": float(len(solver_frame_aligned)),
                "no_market_row_count": float(len(no_market_frame_aligned)),
                "realized_path_row_count": float(len(realized_frame_aligned)),
                "no_market_incumbent_eur": float(no_market_value),
                "realized_path_incumbent_eur": float(realized_value),
                "selected_incumbent_pnl_eur": float(selected.get("value", float("nan"))),
                "selected_total_pnl_eur": float(selected_value),
                "selected_component_pnl_eur": float(selected_component),
                "selected_pnl_balance_error_eur": float(selected_balance_error),
                "selected_pnl_balance_ok": float(
                    np.isfinite(float(selected_balance_error))
                    and abs(float(selected_balance_error)) <= balance_tol
                ),
                "selected_is_solver": float(selected_name == "solver"),
                "selected_is_realized_path_fallback": float(selected_name == "realized_path"),
                "selected_is_no_market_fallback": float(selected_name == "no_market"),
                "no_market_terminal_shortfall_mwh": float(no_market_diag.get("terminal_shortfall_mwh", float("nan"))),
            }

        da_true_for_pf = self._finite_numeric_series(
            perfect_foresight_df,
            colmap.true_da_price,
            fallback_cols=[colmap.pred_da_price],
            default=0.0,
        )
        terminal_price_for_pf = max(
            0.0,
            float(da_true_for_pf.iloc[-1]) if len(da_true_for_pf) else 0.0,
        )

        # Apply stricter/longer solver settings locally for benchmark branches.
        _orig_tl = float(self.milp_time_limit_seconds)
        _orig_gap = float(self.milp_rel_gap)
        self.milp_time_limit_seconds = max(_orig_tl, 300.0)
        self.milp_rel_gap = min(_orig_gap, 1e-4)
        rolling_pf_diag_start = len(self._solver_failure_diagnostics)
        perfect_foresight_dispatch = pd.DataFrame()
        perfect_foresight_plan_history = pd.DataFrame()
        # Same-rules RHPF gets truth-materialized signals but keeps the model's
        # reserve-settlement probability mechanics. A deterministic full-award
        # reserve objective is a different benchmark, not same-rules RHPF.
        rolling_pf_deterministic_reserve_settlement = False
        if benchmark_paths["rhpf"]:
            try:
                try:
                    if use_rolling_horizon:
                        perfect_foresight_dispatch, perfect_foresight_plan_history = self.optimize_dispatch_rolling(
                            perfect_foresight_df,
                            colmap,
                            horizon_hours=horizon_hours,
                            reopt_step_hours=reopt_step_hours,
                            da_bid_hour_local=da_bid_hour_local,
                            soc_feedback_mode=soc_feedback_mode,
                            enforce_final_soc_min=enforce_final_soc_min,
                            deterministic_reserve_settlement=bool(rolling_pf_deterministic_reserve_settlement),
                            is_perfect_foresight=True,
                            allowed_markets=allowed_markets,
                            strategy_name=strategy_name,
                            id_mode=id_mode,
                            id_recourse_mode=id_recourse_mode,
                            run_mode="perfect_foresight",
                            strict_simulation_validity=bool(strict_simulation_validity),
                            bcm_bid_hour_local=bcm_bid_hour_local,
                        )
                    else:
                        perfect_foresight_dispatch = self.optimize_dispatch(
                            perfect_foresight_df,
                            colmap,
                            soc_start=self.soc_init,
                            soc_end_target=None,
                            soc_end_min_target=self.soc_target_end if enforce_final_soc_min else None,
                            deterministic_reserve_settlement=bool(rolling_pf_deterministic_reserve_settlement),
                            allowed_markets=allowed_markets,
                            strategy_permissions=run_strategy_permissions,
                        )
                except RuntimeError as exc:
                    rolling_pf_available = 0.0
                    rolling_pf_verified = 0.0
                    rolling_pf_solver_status = _pf_failure_status(exc)
                    rolling_pf_failure_reason = str(exc)
                    diag = _solver_failure_diag_since(rolling_pf_diag_start)
                    rolling_pf_solver_failure_timestamp_utc = str(diag["timestamp_utc"])
                    rolling_pf_solver_message = str(diag["message"]) or str(exc)
                    rolling_pf_nonfinite_coeff_count = float(diag["nonfinite_coeff_count"])
                    rolling_pf_bad_bound_count = float(diag["bad_bound_count"])
                    pf_failure_reason = f"rolling_pf_solver_failed:{rolling_pf_solver_status}"
                    perfect_foresight_dispatch = pd.DataFrame()
                    perfect_foresight_plan_history = pd.DataFrame()
            finally:
                self.milp_time_limit_seconds = _orig_tl
                self.milp_rel_gap = _orig_gap
        else:
            self.milp_time_limit_seconds = _orig_tl
            self.milp_rel_gap = _orig_gap
        if benchmark_paths["rhpf"]:
            rolling_pf_solver_dispatch_da_buy_mwh = _sum_first_available_mwh(
                perfect_foresight_dispatch,
                [
                    ("da_accepted_buy_mw", True),
                    ("da_selected_lockable_buy_mw", True),
                    ("charge_mw", True),
                    ("plan_charge_mw", True),
                    ("real_da_buy_mwh", False),
                ],
            )
            rolling_pf_solver_dispatch_da_sell_mwh = _sum_first_available_mwh(
                perfect_foresight_dispatch,
                [
                    ("da_accepted_sell_mw", True),
                    ("da_selected_lockable_sell_mw", True),
                    ("discharge_mw", True),
                    ("plan_discharge_mw", True),
                    ("real_da_sell_mwh", False),
                ],
            )
            rolling_pf_da_execution_policy = str(getattr(self, "da_execution_policy", ""))
            rolling_pf_da_price_taker_mode = float(
                str(rolling_pf_da_execution_policy).strip().lower() == "price_taker"
            )
            rolling_pf_da_actual_independent_clearing_applied = float(
                str(rolling_pf_da_execution_policy).strip().lower() == "accepted_independent_limit_replay"
            )
            rolling_pf_da_limit_robust_guard_applied = float(
                str(rolling_pf_da_execution_policy).strip().lower() == "robust_independent_limit"
            )
            rolling_pf_da_truth_price_substitution_applied = float(
                bool(benchmark_paths["rhpf"])
                and colmap.true_da_price in perfect_foresight_df.columns
                and colmap.pred_da_price in perfect_foresight_df.columns
            )
            rolling_pf_da_dispatch_buy_mwh = float(rolling_pf_solver_dispatch_da_buy_mwh)
            rolling_pf_da_dispatch_sell_mwh = float(rolling_pf_solver_dispatch_da_sell_mwh)
            pf_plan_diag = self._rolling_pf_da_plan_history_diagnostics(perfect_foresight_plan_history)
            rolling_pf_da_plan_history_rows = float(pf_plan_diag["rolling_pf_da_plan_history_rows"])
            rolling_pf_da_plan_history_stage_used = str(
                pf_plan_diag.get("rolling_pf_da_plan_history_stage_used", "legacy_unstaged")
            )
            rolling_pf_da_gate_allowed_rows = float(pf_plan_diag["rolling_pf_da_gate_allowed_rows"])
            rolling_pf_da_gate_nonzero_candidate_rows = float(
                pf_plan_diag["rolling_pf_da_gate_nonzero_candidate_rows"]
            )
            rolling_pf_da_raw_candidate_buy_mwh = float(pf_plan_diag["rolling_pf_da_raw_candidate_buy_mwh"])
            rolling_pf_da_raw_candidate_sell_mwh = float(pf_plan_diag["rolling_pf_da_raw_candidate_sell_mwh"])
            rolling_pf_da_sized_candidate_buy_mwh = float(pf_plan_diag["rolling_pf_da_sized_candidate_buy_mwh"])
            rolling_pf_da_sized_candidate_sell_mwh = float(pf_plan_diag["rolling_pf_da_sized_candidate_sell_mwh"])
            rolling_pf_da_postlock_candidate_buy_mwh = float(
                pf_plan_diag["rolling_pf_da_postlock_candidate_buy_mwh"]
            )
            rolling_pf_da_postlock_candidate_sell_mwh = float(
                pf_plan_diag["rolling_pf_da_postlock_candidate_sell_mwh"]
            )
            rolling_pf_da_selected_lockable_buy_mwh = float(
                pf_plan_diag["rolling_pf_da_selected_lockable_buy_mwh"]
            )
            rolling_pf_da_selected_lockable_sell_mwh = float(
                pf_plan_diag["rolling_pf_da_selected_lockable_sell_mwh"]
            )
            rolling_pf_da_zero_trade_stage = str(pf_plan_diag["rolling_pf_da_zero_trade_stage"])
            rolling_pf_da_plan_history_zero_reason = str(pf_plan_diag["rolling_pf_da_plan_history_zero_reason"])
            rolling_pf_da_bid_sizer_status = str(pf_plan_diag["rolling_pf_da_bid_sizer_status"])
            rolling_pf_da_bid_sizer_error = str(pf_plan_diag["rolling_pf_da_bid_sizer_error"])
            rolling_pf_da_bid_sizer_method = str(pf_plan_diag["rolling_pf_da_bid_sizer_method"])
            rolling_pf_da_candidate_support_sizer_used_as_authority = float(
                pf_plan_diag["rolling_pf_da_candidate_support_sizer_used_as_authority"]
            )
            rolling_pf_da_full_window_sizer_diagnostic_status = str(
                pf_plan_diag["rolling_pf_da_full_window_sizer_diagnostic_status"]
            )
            rolling_pf_da_full_window_sizer_diagnostic_reason = str(
                pf_plan_diag["rolling_pf_da_full_window_sizer_diagnostic_reason"]
            )
            rolling_pf_da_path_price_semantics = str(pf_plan_diag["rolling_pf_da_path_price_semantics"])
            rolling_pf_da_bid_sizer_objective_eur = float(pf_plan_diag["rolling_pf_da_bid_sizer_objective_eur"])
            rolling_pf_da_bid_sizer_total_buy_mwh = float(pf_plan_diag["rolling_pf_da_bid_sizer_total_buy_mwh"])
            rolling_pf_da_bid_sizer_total_sell_mwh = float(pf_plan_diag["rolling_pf_da_bid_sizer_total_sell_mwh"])
            rolling_pf_da_bid_sizer_projected_soc_min_mwh = float(
                pf_plan_diag["rolling_pf_da_bid_sizer_projected_soc_min_mwh"]
            )
            rolling_pf_da_bid_sizer_projected_soc_max_mwh = float(
                pf_plan_diag["rolling_pf_da_bid_sizer_projected_soc_max_mwh"]
            )
            rolling_pf_da_bid_sizer_projected_final_soc_mwh = float(
                pf_plan_diag["rolling_pf_da_bid_sizer_projected_final_soc_mwh"]
            )
            rolling_pf_da_candidate_selection_invalid_reason = str(
                pf_plan_diag["rolling_pf_da_candidate_selection_invalid_reason"]
            )
            rolling_pf_da_raw_candidate_pnl_eur = float(pf_plan_diag["rolling_pf_da_raw_candidate_pnl_eur"])
            rolling_pf_da_sized_candidate_pnl_eur = float(pf_plan_diag["rolling_pf_da_sized_candidate_pnl_eur"])
            rolling_pf_da_terminal_recovery_actually_written = float(
                pf_plan_diag["rolling_pf_da_terminal_recovery_actually_written"]
            )
            rolling_pf_da_terminal_recovery_cost_included = float(
                pf_plan_diag["rolling_pf_da_terminal_recovery_cost_included"]
            )
            rolling_pf_da_terminal_binding_id_repair_written = float(
                pf_plan_diag["rolling_pf_da_terminal_binding_id_repair_written"]
            )
            rolling_pf_da_sized_zero_reason = str(pf_plan_diag["rolling_pf_da_sized_zero_reason"])
            rolling_pf_da_first_sized_zero_ts_utc = str(pf_plan_diag["rolling_pf_da_first_sized_zero_ts_utc"])
